window.SOURCE_BOOKS=window.SOURCE_BOOKS||{};window.SOURCE_BOOKS["tang_cai_zi_zhuan"]={"id":"tang_cai_zi_zhuan","title":"唐才子传","author":"元·辛文房","edition":"四库全书辑本","description":"四库辑本正文八卷；收唐代诗人生平、科第、交游、作品风格与评价。","source":"中文维基文库","sourceUrl":"https://zh.wikisource.org/wiki/唐才子傳_(四庫全書本)","license":"CC BY-SA 4.0","chapters":[{"title":"唐才子传 (四库全书本)","text":"钦定四库全书 史部七\n唐才子传 传记类三〈总录之属〉提要\n〈臣〉等谨案唐才子𫝊八巻元辛文房撰文房字良史西域人其始末不见於史𫝊惟陆友仁研北杂志称其能诗与王执谦齐名苏天爵元文类中载其苏小小歌一篇耳是书原本凡十巻总三百九十七人下至妓女女道士之类亦皆载入其见於新旧唐书者仅百人余皆从𫝊记説部各书采葺其体例因诗系人故有唐名人非卓有诗名者不录即所载之人亦多详其逸事及着作之𫝊否而於功业行谊则只撮其梗概葢以论文为主不以记事为主也大抵於初盛稍略中晚以後渐详至李建勲孙鲂沈彬江为廖图熊皦孟賔于孟贯陈搏之伦均有専𫝊则并下𮎛五代矣考杨士竒东里集有是书跋是明初尚有完帙故永乐大典目录於𫝊字韵内载其全书今𫝊字一韵适佚世间遂无𫝊本然幸其各韵之内尚杂引其文今随条摭拾裒辑编次共得二百三十四人又附𫝊者四十四人共二百七十八人谨依次订正厘为八巻按杨士竒跋称是书凡行事不闗大体不足为劝戒者不录又称杂以臆説不尽可据今考编中如许浑𫝊称其梦游崑仑李羣玉𫝊称其梦见神女杂采孟棨本事诗范摅云溪友议荒唐之説无当史裁又如储光羲汚禄山伪命而称其养浩然之气尤乖大义他如谓骆賔王与宋之问唱和灵隠寺中谓中兴间气集为髙适所选谓李啇隠曽为广州都督谓唐人效杜甫者惟唐彦谦一人乖舛不一而足葢文房抄掇繁实或未暇检详故谬误抵牾往往杂见然较计有功唐诗纪事叙述差有条理文笔亦秀润可观𫝊後间缀以论掎摭诗家利病亦足以津逮艺林於学诗考订之助固不为无补焉乾隆四十六年九月恭校上\n总纂官〈臣〉纪昀〈臣〉陆锡熊〈臣〉孙士毅\n总 校 官 〈臣〉陆 费 墀\n\n全览\n\n巻一\n\n巻二\n\n巻三\n\n巻四\n\n巻"},{"title":"巻一","text":"钦定四库全书\n唐才子传巻一 元 辛文房 撰\n崔信明 李百药\n王 勃 杨 烱\n卢照邻〈兄光乘〉 骆賔王\n宋之问 沈佺期\n杜审言〈孙甫〉 李 峤\n刘希夷 陈子昂\n张 説 王 翰\n贺知章 张子容\n王 湾 李 昂\n孙 逖 王泠然\n崔 颢 刘眘虚\n祖 咏 綦毋潜\n崔国辅 储光羲\n王昌龄 常 建\n陶翰\n崔信明〈案新旧唐书信明青州益都人〉少英敏及长强记美文章髙孝基语人曰崔生才冠一时但恨位不到耳为尧城令窦建徳僭号信明弟仕贼劝信明降节当得美官不肯从遂踰城去隐太行山中贞观中诏即其家拜兴世丞迁秦川令〈按崔信明传永乐大典所载止得二条盖全文已佚矣今谨就原文编录附识扵此〉\n李百药〈按新唐书百药字重规定州安平人〉才行天下推服好奬㧞後进翰藻沉郁〈按此条有阙文〉\n王勃〈按新旧唐书勃字子安绦州龙门人〉六嵗善辞章未及冠授朝散郎沛王署为府修撰诸王鬬鸡㑹勃戏为文檄髙宗闻之怒斥出府既废父福畤迁交址令勃徃省觐途过南昌时都督阎公新造滕王阁成九月九日大㑹賔客将令其壻作记以夸盛事勃至入谒帅知其才因请为之勃欣然对客操觚顷刻而就文不加㸃满座大惊辞别帅赠百缣即举帆去勃属文绮丽请者甚多金帛盈积心织而衣笔耕而食有集三十巻及舟中纂序五巻今行於世勃尝遇异人相之曰子神强骨弱气清体羸胸骨亏陷目睛不全秀而不实终无大贵矣溺海时年二十九故其才长而命短者岂非相乎\n杨烱〈按新旧唐书烱华隂人〉博学善属文六嵗举神童授校书郎永隆二年皇太子舍奠表豪俊充崇文馆学士後为盈川令张説以箴赠之戒其苛刻至官以刻称卒烱恃才凭傲每耻朝士矫饰呼为麒麟楦或问之曰今弄假麒麟戏者必刻画其形覆驴上宛然异物及去其皮还是驴耳闻者甚不平故为时所忌与王勃卢照隣骆賔王以文辞齐名海内称四才子亦曰四杰效之者风靡焉烱曰吾愧在卢前耻居王後论者然之张説曰盈川文如悬河酌之不竭优於卢而不减於王愧在卢前谦也耻在王後信然有盈川集三十巻\n卢照隣字昇之范阳人调邓王府典籖王爱重谓人曰此吾之相如也後迁新都尉婴病去官居太白山草阁得方士𤣥明膏饵之㑹父䘮号恸因呕丹輙出疾愈甚家贫苦贵宦时时供衣药乃去具茨山下买园数十畆䟽颍水周舍复豫为墓偃卧其中自以当髙宗时尚吏已独儒武后尚法已独黄老后封嵩山屡聘贤士己已废着五悲文以自明手足挛缓不起行已十年毎春归秋至云壑烟郊輙舆出户庭悠然一望遂自伤作释疾文有云覆焘虽广嗟不容乎此生亭育虽繁恩已絶乎斯代与亲属诀自沉颍水有诗文二十巻及幽忧子三巻行於世旧唐书曰兄光乘亦知名长夀中为陇州刺史\n骆賔王义乌人七嵗能赋诗武后时数上䟽言事得罪贬临海丞鞅鞅不得志弃官去文明中徐敬业起兵欲反正徃投之署为府属为敬业作檄𫝊天下暴斥武后罪恶后见读之矍然曰谁为之或以賔王对后曰有如此才不用宰相过也及败亡命不知所之後宋之问贬还道出钱塘游灵隐寺夜月行吟长廊下曰鹫岭欝迢嶤龙宫隐寂寥未得下聨有老僧然灯坐禅问曰少年不寐而吟讽甚苦何耶之问曰欲题此寺而思不属僧笑曰何不道楼观沧海日门对浙江潮之问终篇曰桂子月中落天香云外飘扪萝登塔逺刳木取泉遥云薄霜初下氷轻叶未凋待入天台路㸔余度石桥僧一聨篇中警䇿也迟明访之已不见老僧即賔王也𫝊闻浮海而去矣後中宗诏求其文得百余篇及诗等十巻命㕁云卿次序之及百道判集一巻今𫝊於世\n宋之问〈按新唐书云之问字延清一名少连汾州人而旧唐书则云虢州𢎞农人〉伟貎辨给甫冠武后召与杨烱分直习艺馆累转尚方监丞后游龙门诏从臣赋诗左史东方虬诗先成后赐锦袍之问俄顷献后览之嗟赏更夺袍以赐〈按此条有阙文〉\n沈佺期〈按新旧唐书佺期字云卿相州内黄人〉上元二年郑益榜进士工五言常侍宫中佺期尝以诗赠张燕公公曰沈三兄诗清丽须让居第一也诗名大振自魏建安迄江左诗律屡变至沈约鲍照庾信徐陵以音韵相婉附属对精致及佺期之问又加靡丽回忌声病约句准篇着定格律遂成近体如锦绣成文学者宗尚语曰苏李居前沈宋比肩谓唐诗变体始自二公犹汉人五字诗始自苏武李陵也有集十巻今𫝊扵世\n杜审言〈按新唐书审言字必简襄州襄阳人〉预之逺裔咸亨元年宋守节榜进士为隰城尉恃髙才傲世坐事贬吉州司户及武后召还将用之问曰喜否审言舞蹈谢后令赋欢喜称㫖授着作郎为修文馆直学士杜甫其孙也\n甫〈按此下有阙文〉禄山乱避走三川寓鄜弥年弃官客秦州㑹严武节度剑南西川徃依焉武以世旧待甫甚善亲诣其家甫见之或时不巾而性褊躁傲诞尝醉登武牀瞪视曰严挺之乃有此儿武中衔之一日欲杀甫集吏扵门武将出冠鈎扵帘者三左右走报其母力救得止〈按本书包融传论凡唐人中父子兄弟并着才名者辛文房均盛述之知原书扵家世有文者皆合为一𫝊甫为审言之孙自应附审言𫝊後谨发其凡扵此〉\n李峤〈按新唐书峤字巨山赵州赞皇人〉前与王勃杨烱接中与崔融苏味道齐名晚诸人没为文章宿老学者取法焉〈按此条有阙文〉刘希夷〈按旧唐书希夷汝州人〉美姿容好谈笑善弹琵琶饮酒至数斗不醉落魄不拘常检尝吟诗曰年年嵗嵗花相似嵗嵗年年人不同宋之问苦爱此一聫知其未𫝊扵人恳求之许而竟不与之问怒其诳巳使以土囊压杀扵别舍时未及三十人悉怜之\n论曰希夷天赋俊爽才情如此想其事业勲名何所不至而为之问压杀昔者襧衡痛江夏之来倐焉折首夫何殒命以隋侯之珠弹雀所较者轻所失者重玉迸松摧良可惜也况扵骨肉相残者乎\n陈子昂〈按新唐书子昂字伯玉梓州射洪人〉开耀二年许旦榜进士初年十八时未知书以富家子任侠尚气弋博後入乡校感悔即於州东南金华山观读书痛自修饰精究坟典耽爱黄老易庄光宅元年诣阙上书谏灵驾入京武后召见竒其才遂拜麟台正字诏云地籍英华文称暐累迁拾遗子昻貎柔雅而性褊躁轻财好施笃朋友之义与逰英俊多秉钧衡唐兴文章承徐庾余风天下祖尚子昂始变雅正初为感遇诗三十章王适见而惊曰此子必为海内文宗由是知名有集一巻今𫝊\n张説〈按新唐书説字道济一字説之洛阳人〉睿宗时兵部侍郎同平章事开元十八年终左丞相説敦气节重然诺为文精壮长扵碑志朝廷大述作多出其手诗法特妙晚谪岳阳诗益凄惋人谓得江山之助〈按此条有阙文〉\n王翰〈按新唐书翰字子羽并州晋阳人〉景云元年卢逸下进士及第又举直言极諌又举超拔羣类科少豪荡恃才不羁喜纵酒枥多名马家蓄妓乐翰发言立意自比王侯日聚英杰从禽击鼓为欢张嘉贞为本州长史厚遇之翰酒间自歌诗以舞属嘉贞神气轩举张説尤加礼异及辅政召为正字擢驾部员外郎説罢翰出为仙州别驾以穷乐畋饮贬岭表道卒翰工诗多壮丽之词文士祖咏杜华等尝与逰从华母崔氏云吾闻孟母三迁吾今欲卜居使汝与王翰为邻矣其才如此燕公论其文如琼杯玉斚虽烂然可珍而多玷缺云有集今𫝊\n论曰太史恨布衣之侠湮没无闻以其义在存亡死生之间而不伐其徳千金驷马奚啻草芥信哉名不虚立也观王翰之气其若人之俦乎\n贺知章〈按旧唐书知章㑹稽永兴人〉以文词知名性旷夷善谈论笑谑陆象先在中书引为太常博士象先与知章最亲善常曰季真清谈风韵吾一日不见则鄙吝生矣当时贤逹皆倾慕之天寳三年因病梦逰帝居及寤表请为道士求还乡里即舍住宅为千秋观上许之诏赐镜湖剡溪一曲以给渔樵後改为天长观\n张子容开元元年常无名榜进士为乐城令初与孟浩然同隐鹿门山为死生交诗篇唱答颇多後值乱离流寓江表尝送内兄李录事归故里云十年多难与君同几处移家逐转蓬白首相知征战後青春已过乱离中行人杳杳看西月归马萧萧向北风汉水楚云千万里天涯此别恨无穷後弃官归旧业\n王湾开元元年常无名榜进士与学士綦毋潜契切词翰早着为天下所称徃来吴楚间多有着述如江南意一聨云海日生残夜江春入旧年诗人以来罕有此作张燕公手题扵政事堂毎示能文令为楷式曽奉使登终南山有赋志趣髙逺识者不能弃焉\n李昂开元二年王丘下状元及第天寳间仕为礼部侍郎知贡举奬拔寒素甚多〈按新唐书选举志开元二十四年考功员外郎李昂为举人诋诃帝以员外郎望轻遂移贡举於礼部以侍郎主之礼部选士自此始则昻之知贡举未协舆论可知原文所云殊非事实〉工诗有戚夫人楚舞歌篇播𫝊人口真佳作也\n孙逖博州人㓜而有文属辞警敏援笔成篇开元二年举手笔俊拔哲人竒士隐沦屠钓及文藻宏丽等科第一人及第𤣥宗引见擢左拾遗集贤殿修撰改考功员外郎迁中书舍人与顔真卿李华萧頴士皆同时称海内名士〈按旧唐书逖𫝊开元二十一年逖始为考功员外郎频选贡士初年得顔真卿後年得李华萧颖士考文献通考开元二十一年至二十三年嵗一试进士科盖皆逖主之三人者其所取士也又考旧唐书所载开元二十四年逖始迁中书舍人原文未为明晰又此条有阙文并识扵此〉\n王泠然山东人开元五年裴耀卿下进士授将仕郎守太子校书郎工文赋诗气质豪爽当言无所回忌卓荦竒才济世之器惜其不大显而终有集今𫝊\n崔颢〈按新旧唐书颢汴州人书录解题颢开元十年进士〉好蒱博嗜酒娶妻择美者稍不惬即弃之凡易三四初李邕闻其才名虚舍邀之颢至献诗首章云十五嫁王昌邕叱曰小儿无礼天寳中为尚书司勲员外郎少为诗意浮艳多陷轻薄晚节忽变常体风骨凛然一窥塞垣状极戎旅竒造徃徃并驱江鲍後㳺武昌登黄鹤楼感慨赋诗及李白来曰眼前有景道不得崔颢题诗在上头无作而去为哲匠敛手颢生平苦吟咏当病起清虚友人戯之曰非子病如此乃苦吟诗瘦耳遂为口实\n刘眘虚嵩山人姿容秀㧞九嵗属文上书召见拜童子郎开元十一年徐徴榜进士调洛阳尉迁夏县令性髙古脱畧势利啸傲风尘後欲卜隐庐阜不果交逰多山僧道侣为诗情幽兴逺思雅词竒忽有所得衆便惊听当时东南髙唱者数十人声律宛态无出其右〈按此条有阙文〉祖咏〈按书録解题咏开元十二年进士〉少与王维为吟侣维在济州寓官舍赠祖三诗有云结交二十载不得一日展贫病子既深契阔余不浅盖亦流落不偶极可伤也\n綦毋潜荆南人〈按新唐书艺文志注潜字孝通〉开元十四年严廸榜进士授宜夀尉迁右拾遗入集贤院待制复授校书终着作郎与李端同时诗调屹崒峭蒨足佳句善写方外之情後见兵乱官况日恶挂冠归隐江东别业王维有诗送之曰明时久不逹弃置与君同天命无怨色人生有素风一时文士咸赋诗祖饯有集一巻行世\n崔国辅山隂人也开元十四年严廸榜进士与储光羲綦毋潜同时举县令累迁集贤直学士礼部郎中天寳间坐是王鉷近亲贬竟陵司马有文及诗婉娈清楚深宜讽咏乐府短章古人有不能过也初至竟陵与处士陆鸿渐游三嵗交情至厚谑笑永日又相与较定茶水之品临别谓羽曰予有襄阳太守李憕所遗白驴乌犎牛各一头及卢黄门所遗文槐书函一枚此物皆已之所惜者宜野人乘蓄故特以相赠雅意髙情一时所尚有酬酢之歌诗并集𫝊焉\n储光羲兖州人开元十四年严廸榜进士有诏中书试文章尝为监察御史值安禄山陷长安輙受伪署贼平後自归贬死岭南工诗格髙调逸趣逺情深削尽常言挟风雅之道养浩然之气览者犹聆韶濩音先洗桑濮耳庶几乎赏音也有集七十巻政论十五巻九经分义疏二十巻并𫝊\n王昌龄字少伯太原人开元十五年李岩榜进士授泛水尉又中宏辞迁校书郎复以不䕶细行贬龙标尉以刀火之际归乡里为刺史闾丘晓所忌而死後张镐按军河南晓愆期将戮之辞以亲老乞恕镐曰王昌龄之亲欲与谁养乎晓大惭沮昌龄工诗绪宻而思清时称诗家夫子王江寜盖尝为江寜令与文士王之涣辛渐交友至深皆出模范其名重如此有诗集五巻又述作诗格律境思体例共十四篇为诗格一巻又诗中宻㫖一巻及古乐府解题一巻今并𫝊\n论曰自元嘉以还四百年之内曹刘陆谢风骨顿尽逮储光羲王昌龄颇从厥迹两贤气同而体别也王稍声峻竒句俊格惊耳骇目奈何晚途不矜小节谤议腾沸两窜遐荒使知音者喟然长叹至归全之道不亦痛哉常建长安人开元十五年与王昌龄同榜登科大厯授盱眙尉仕颇不如意遂放浪琴酒徃来太白紫阁诸峯有肥遯之志尝采药山谷中遇女子遍体緑毛自言是秦时宫人亡入山来食松叶遂不饥寒因授建㣲㫖所养非常後寓鄂渚招王昌龄张偾同隐获大名当时集一巻今𫝊\n论曰古称髙才而无贵仕诚哉是言曩刘桢死扵文学鲍照卒扵参军今建亦沦於一尉悲夫建属思既精词亦警絶似初发通庄却寻野径百里之外方归大道㫖逺兴僻能论意表可谓一唱而三叹矣\n陶翰润州人开元十八年崔明允下进士及第次年中博学宏辞与郑昉同时官至礼部员外郎为诗词笔双美既多兴义复备风骨三百年以前方可论其裁制"},{"title":"巻二","text":"钦定四库全书\n唐才子传巻二 元 辛文房 撰\n王 维 孟浩然\n殷 遥 薛 据\n李颀 崔 曙\n张 諲 李 白\n岑 参 髙 适\n王之涣 包 融〈子何佶〉\n阎 防 丘 为\n卢 象〈韦述〉 张 谓\n贾 至 沈千运\n孟云卿 王季友\n康 洽 刘长卿\n韦应物 钱 起〈子徽 懐素孙珝〉\n张 继 韩 翃\n郎士元 皇甫冉〈弟曽〉\n独孤及 戎 昱\n王维九嵗知属辞工草𨽻娴音律岐王重之维将应举岐王谓曰子诗清越者可録数篇琵琶新声能度一曲同诣九公主第维如其言是日诸伶拥维独奏主问何名曰郁轮袍因出诗巻主曰皆我习讽谓是古作乃子之佳制乎延于上座曰京兆得此生为解头荣哉力荐之开元十九年状元及第擢右拾遗迁给事中贼陷两京驾出幸维扈从不及为所擒服药称瘖病禄山爱其才逼至洛阳供旧职拘于普施寺贼宴凝碧池悉召梨园诸工合乐维痛悼赋诗曰万户伤心生野烟百官何日再朝天秋槐花落空宫里凝碧池头奏管诗闻行在贼平後伪官皆定罪独维得免仕至尚书右丞维诗入妙品上上画思亦然至山水平逺云势石色皆天机所到非学而能自作诗云当代谬词客前身应画师人评维诗中有画画中有诗信哉中嵗丧妻不再娶孤居三十年别墅在蓝田县南辋川亭馆相望自写其景物竒胜日与文士丘为裴迪崔兴宗逰览赋诗琴樽自乐笃志奉佛蔬食素衣後表请舍宅以为寺临终作书辞亲友停笔而化\n孟浩然〈按新唐书浩然字浩然襄阳人〉少好节义诗工五言隠鹿门山即龎公栖隠处也四十逰京师诸名士间尝集秘省聮句浩然曰㣲云淡河汉疎雨滴梧桐衆钦服张九龄王维极称道之维待诏金銮一旦私邀入商较风雅俄报𤣥宗临幸浩然错愕伏匿牀下维不敢隠因奏闻帝喜曰朕素闻其人而未见也诏出再拜帝问曰卿将诗来耶对曰偶不齎即命吟近作诵至不才明主弃多病故人疎之句帝怃然曰卿不求仕朕何尝弃耶奈何诬我因命放还南山古称祢衡不遇赵壹无禄观浩然罄折谦退才名日髙竟沦明代终身白衣良可悲夫其诗文采丰茸经纬绵宻半遵雅调全削凡近所着三巻今𫝊王维画浩然像于郢州为浩然亭咸通中郑諴谓贤者名不可斥更曰孟亭今存焉\n殷遥丹阳人天宝间尝仕为忠王府仓曹㕘军与王维结交同慕禅寂志趣髙疎多云岫之想而苦家贫死不能𦵏一女才十嵗日哀号于亲爱怜之者賵赠埋骨石楼山中工诗词彩不羣而多警句杜甫尝称许之有诗𫝊于今\n薛据荆南人开元十九年王维榜进士天宝六年又中风雅古调科第一人于吏部㕘选据自恃才名请受万年録事流外官诉宰执以为赤县是某等清要据无由得之改涉县令後仕歴司议郎终水部郎中据为人骨鲠有气魄文章亦然尝自伤不得早达造句往往追凌鲍谢初好栖迟居嵩山链药晚嵗置别业终南山下老焉有集今𫝊\n李颀东川人开元二十三年贾季隣榜进士及第调新乡县尉性疎简厌薄世务慕神仙服饵丹砂期轻举之道结好尘喧之外一时名辈莫不重之工诗发调既清修辞亦秀杂歌咸善𤣥理最长多为放浪之语足可震荡心神惜其伟材只到黄绶故其论道家往往髙于衆作有集今𫝊\n崔曙宋州人〈按书録解题曙开元二十六年状元及第〉少孤贫不应荐辟志况疎爽择交于方外苦读书髙栖少室山中与薛据友善工诗言词欵要情兴悲凉送别登楼俱堪泪下有集𫝊于今\n张諲永嘉人初隠少室山下闭门修肄志甚勤苦不及声利後应举官至刑部员外郎明易象善草𨽻兼画山水诗格髙古与李颀友善事王维为兄皆为诗酒丹青之契维赠诗云屏风误㸃惑孙郎团扇草书惊内史李颀赠曰小王破体闲支䇿落月梨花照空壁诗堪记室妬风流画与将军作劲敌天寳中谢官归故山偃仰不复来人间矣有诗𫝊世\n李白山东人母梦长庚星而诞因以命之十嵗通五经夜梦笔头生花後天才赡逸名闻天下天宝初自蜀至长安道㩦所业投贺知章读至蜀道难叹曰子谪仙人也乃解金龟换酒终日相乐遂荐于𤣥宗召见金銮殿论时事因奏颂一篇帝喜赐食亲为调羮诏供奉翰林尝大醉上前草诏使髙力士脱鞾力士耻之晚节好黄老度牛渚矶乗醉捉月遂沉水中〈按白传有阙文今就永乐大典所载五条编次〉岑参南阳人文本之後天宝三年赵岳榜第二人及第累官左补阙起居郎出为嘉州刺史杜鸿渐表置安西幕府拜职方郎中兼侍御史辞罢别业在杜陵山中後终于蜀参累佐戎幕往来鞍马烽尘间十余载极征行离别之情城障塞堡无不经行博览史籍尤工缀文属词清迥用心良苦诗调尤髙唐兴罕见此作放情山水故常懐逸念竒造幽致所得往往超拔孤秀度越常情与髙适风骨颇同读之令人慷慨懐感毎篇絶笔人辄𫝊咏至徳中裴休杜甫等常荐其识度清逺议论雅正嘉名早立时辈所仰可以备献替之官未及大用而谢世岂不伤哉有集十巻行于世杜确为之序云髙适字达夫一字仲武沧州人少性拓落不拘小节耻预常科隠迹博徒才名便逺後举有道授封丘尉擢諌议大夫负气敢言权贵侧目适尚气节语王覇衮衮不厌遭时多难以功名自许五十始学为诗即工以气质自髙多胸臆间语毎一篇已好事者辄𫝊播吟玩尝过汴州与李白杜甫㑹酒酣登吹台慷慨悲歌临风懐古人莫测也中间唱和颇多今有诗文等二十巻及所选至徳迄大厯述作者二十六人诗为中兴间气集二巻并𫝊〈按适𫝊有阙文〉\n王之涣蓟门人少有侠气所从逰皆五陵少年击剑悲歌从禽纵酒後折节工文十年名誉自振耻困屋遂交谒名公为诗情致雅畅得齐梁之气毎有作乐工辄取以被声律与王昌龄髙适畅当忘形尔汝尝共诣旗亭有梨园名部至昌龄等曰我辈擅诗名未定甲乙可观诗伶讴诗以多者为优一伶唱昌龄二絶句一唱适一絶句之涣曰乐人所唱皆下俚之词须㬰一佳妓唱曰黄河逺上白云间一片孤城万仞山羌笛何须怨杨栁春风不度玉门闗复唱二絶皆之涣词三子大笑曰田舍奴吾岂妄哉诸伶竟不谕其故拜曰肉眼不识神仙三子从之酣醉终日其狂放如此云有诗𫝊于今包融延陵人开元间仕厯大理司直与参军殷遥孟浩然交厚工为诗二子何佶纵声雅道齐名当时号三包有诗一巻行世\n论曰夫人之于学苦心难既苦心成业难成业者获名不朽兼父子兄弟间尤难厯观唐人父子如三包六窦张碧张瀛顾况顾非熊章孝标章碣杜审言杜甫钱起钱珝温庭筠温宪弟兄如皇甫冉皇甫曽李宣古李宣逺姚系姚伦等皆聮玉无瑕清尘逺播芝兰继芳重难改于父道骚雅接响庶不慊于祖风四难之间挥麈之际亦可以为美谈矣\n何字幼嗣润州延陵人融之子也与弟佶俱以诗鸣时称二包天寳七年杨誉榜及第曽师事孟浩然授格法与李嘉佑相友善大厯中仕终起居舍人诗𫝊者可数葢流离世故率多素辞大播芳名亦以当时望族也佶〈按唐诗纪事佶字㓜正〉天寳六年杨䕶榜进士累迁秘书监未几迁刑部侍郎太常少卿拜谏议大夫御史中丞居官谨确所在有声佶天才赡逸气宇清深心醉古经神和大雅诗家老斵轮也与刘长卿窦叔向诸公皆莫逆之爱晚嵗沾风痹之疾辞宠乐髙不及荣利卒封丹阳郡公有诗集行于世\n阎防河中人开元二十二年李琚榜及第顔真卿甚敬爱之欲荐于朝不屈为人好读书好古博雅诗语真素魂清魄爽放旷山水髙情独诣于终南山丰徳寺结茅茨读书百丈溪是其隠处题诗云浪蹟弃人世还山自幽独始傍巢由踪吾其获心曲又云养闲废人事达命知止足不学鲁国儒俟时劳伐辐後信命不务进取以此自终有诗集行世\n丘为〈按新唐书艺文志注为苏州嘉兴人〉天寳初刘单榜进士官至太子右庶子事母孝年八十余致仕还县令谒之为𠉀门磬折令坐方拜里胥立庭下既出乃敢坐经县署降马而过举动有礼卒年九十六有集行世\n卢象字纬卿汶水人鸿之侄也携家来居江东最乆仕为校书郎左拾遗膳部员外郎授安禄山伪官贬永州司户参军後为主客员外郎有诗名誉满秘阁雅而不俭有大体得国士之风集二十巻今𫝊同仕有韦述为桑泉尉时诏求逸书命述等编校于朝元殿後为翰林学士有诗名今亦𫝊焉〈按卢象为鸿之侄此𫝊本当附鸿𫝊後以鸿入隠逸𫝊与象出处异揆故分编焉〉\n张谓字正言河内人也〈按唐诗纪事谓登天宝二年进士第〉少读书嵩山清才㧞萃泛览流观不屈于权势自矜竒骨必谈笑封侯二十四受辟从戎营朔十载亭障间稍立功勲以将军得罪流滞蓟门有以非辜雪之者累官为礼部侍郎无几何出为潭州刺史性嗜酒简淡乐意湖山工诗格度严宻语致精深多击节之音今有集𫝊于世\n贾至〈按新唐书至字㓜邻陈振孙书録解题则以为字㓜几〉洛阳人曽之子也天宝擢第官起居舍人知制诰从幸西蜀当撰𫝊位肃宗册文既进藁𤣥宗曰先天诰命乃父所为今兹大册尔又为之两朝盛典出卿家父子可谓继美矣〈按贾至𫝊有关文〉沈千运吴兴人工旧体诗气格髙古当时士流皆敬慕之号为沈四山人天宝中数应举不第时年齿已迈遨逰襄邓间干谒名公来濮上感懐赋诗曰圣朝优贤良草泽无遗族人生各有命在余胡不淑一生但区区五十无寸禄衰落当弃捐贫贱招谤讟其时多难自知屯蹇遂浩然有归欤之志赋诗曰栖隠非别事所愿离风尘不来城邑逰礼乐拘束人又曰如何巢与由天子不得臣遂还山中别业尝曰衡门之下可以栖迟有薄田园儿稼女织偃仰今古自足此生谁能作小吏走风尘下乎髙适赋还山吟赠行曰还山吟天髙日暮寒山深送君还山识君心人生老大须恣意看君解作一生事山间偃仰无不至石泉淙淙若风雨桂花松子常满地卖药囊中应有钱还山服药又长年白云劝尽杯中物明月相随何处眠眠时忆问醒时意梦魂可以相周旋肃宗议备礼徵致㑹卒而罢有诗𫝊世\n孟云卿闗西人天宝间不第气颇难平志亦髙尚懐嘉遯之节与薛据相友善尝寓荆州杜工部有与云卿赠答之作甚爱重之工诗其体祖述沈千运渔猎陈拾遗词气伤感虽然模效才得升堂犹未入室然当时古词无出其右一时之英也如虎豹不相食哀哉人食人又朝亦常苦饥暮亦常苦饥飘飘万里余贫贱多是非少年莫逺逰逺逰多不归皆为当代推服韦应物过广陵遇孟九赠诗云髙文激颓波四海靡不𫝊西施且一笑衆女安得妍其才名于此可见矣仕终校书郎有集今𫝊\n论曰云卿禀通济之才沦吞噬之俗栖栖南北苦无所遇何生之不辰也身处江湖心存魏阙犹杞国之人忧天坠相率而逃者匹夫之志亦可念矣\n王季友河南人暗诵书万巻论必引经家贫卖屐好事者多㩦酒就之其妻栁氏疾季友穷丑遣去来客丰城洪州刺史李公一见倾敬即引佐幕府工诗性磊落不羁爱竒务险逺出常情之外白首短褐﨑岖士林伤哉贫也尝有诗云山中谁余宻白发日相亲雀鼠昼夜无知我厨廪贫又自耕自刈食为天如鹿如麋饮野泉亦知世上公卿贵且养丘中草木年观其笃志山水可谓逺性风疎逸情云上矣有集𫝊于世\n康洽酒泉人黄髪美丈夫也盛时携琴剑来长安谒当道气度豪爽工乐府诗篇宫女梨园皆写于声律𤣥宗亦知名尝叹美之所出入皆王侯贵主之宅从逰与讌虽骏马苍头如其已有观服玩之光令人欲惜物怜才乃能如是也後遭天宝乱离飘蓬江表至大歴间年已七十余龙锺衰老谈及开元繁盛流涕无从往来两京故侯馆谷空咸阳一布衣耳于时文士愿与论交李端逢之赠诗云声名常压鲍参军班位不过扬执㦸又云同时献赋人皆尽共壁题诗君独在後卒杜陵山中文章不得见矣\n刘长卿〈按新唐书艺文志云长卿字文房〉河间人少居嵩山读书後移家鄱阳开元中徐徵榜及第歴监察御史出为转运使判官後观察使吴仲孺诬奏非罪贬南巴尉㑹有为辨之者量移睦州司马终随州刺史长卿清才冠世颇淩浮俗性刚多忤权门故两逢迁斥人悉寃之诗调雅畅甚能链饰其自赋伤而不怨足以发挥风雅权徳舆称为五言长城尝谓今人称前有沈宋王杜後有钱郎刘李李嘉佑郎士元何得与余并驱毎题诗不言姓但书长卿天下无不知其名者有诗集赋文𫝊世\n章应物〈按书録解题应物京兆人〉尚侠初以三卫郎事𤣥宗後始折节读书为性髙洁鲜食寡欲所居必焚香扫地而坐㝠心象外〈按此𫝊有阙文〉\n钱起字仲文吴兴人天宝十年李巨卿榜及第少聪敏承乡曲之誉初从计吏至京口客舍月夜闲歩闻户外有行吟声哦曰曲终人不见江上数峰青凡再三往来起遽从之无所见矣怪之及就试粉闱诗题乃湘灵鼓瑟起缀就即以鬼謡十字为落句主文李暐深嘉美击节吟味乆之曰是必有神助之耳遂擢置髙第释褐授校书郎尝采箭竹奉使入蜀除考功郎中大厯中为太清宫使翰林学士起诗体制新竒理致清赡芟宋齐之浮㳺削梁陈之曼靡迥然独立也王右丞许以髙格与郎士元齐名士林语曰前有沈宋後有钱郎集十巻今传子徽孙珝并能诗外甥怀素善书一门之中艺名森出可尚矣\n论曰凡唐人燕集祖送必探题分韵赋诗于衆中推一人擅者刘相巡察江淮诗人满坐而起擅郭暧尚主盛㑹李端擅缅懐盛时往往文㑹羣贤毕集觥筹乱飞遇江山之佳丽继欢好于畴昔良辰美景赏心乐事于斯能并矣况賔无絶缨之嫌主无投辖之困歌䦨舞作㣲闻香泽冗长之礼豁畧去之王公不觉其大韦布不觉其小忘形尔汝促席谈谐吟咏继来挥毫惊座乐哉古人有秉烛夜逰所谓非浅同宴一室无及于乱岂不盛也至若残盃冷炙一献百拜察喜怒于眉睫之间者可以休矣\n珝〈按唐诗纪事珝字端文〉吴兴人起之孙也乾宁六年郑蔼榜及第昭宗时仕为中书舍人工诗有集𫝊于世\n张继字懿孙襄州人天宝十二年礼部侍郎杨浚下及第与皇甫冉有髫年之故契逾昆玉早振词名初来长安颇矜气节有感懐诗云调与时人背心将静者论终年帝城里不识五侯门尝佐镇戎军幕府又为盐铁判官大歴间仕终检校祠部郎中继博览有识好谈论知治体亦尝领郡辄有政声诗情爽激多金玉音盖其累代词伯积袭弓裘其于为文不雕不饰丰姿清迥有道者风集一巻今𫝊\n韩翃字君平南阳人天宝十三年杨紘榜进士侯希逸素重其才至是表佐淄青幕府罢闲居十年及李勉在宣武复辟之徳宗时制诰阙人中书两进除目御笔不㸃再请之批曰与韩翃时有同姓名为江淮刺史宰相请孰与上复批曰春城无处不飞花韩翃也俄以驾部郎中知制诰终中书舍人翃工诗兴致繁富如芙蓉出水一篇一咏朝士珍之比讽深于文房筋节成于茂政当时盛称焉有诗集五巻行于世\n郎士元字君胄中山人也天宝十五载卢庚榜进士宝应初选京畿县官诏试政事中书补渭南尉歴左拾遗出为郢州刺史与员外郎钱起齐名时朝廷自丞相以下出牧奉使无两君诗文祖饯人以为愧其珍重如此二公体调大抵欲同就中郎君稍更闲雅逼近康乐珠聮玉映不觉成编掩映时流名不虚矣有别业在半日吴村王季友钱起等皆见题咏毎夸胜絶诗集今𫝊于世皇甫冉字茂政安定人避地来寓丹阳耕山钓湖放适闲淡或云秘书少监彬之侄也十嵗能属文张九龄一见叹以清才天宝十五年卢庚榜进士调无锡尉营别墅阳羡山中大歴初王缙为河南节度辟掌书记後入为左金吾卫兵曹参军仕终拾遗左补阙冉自擢桂礼闱便称髙格往以世道艰虞避地江外故多飘薄之叹毎文章一到朝廷而作者变色当年才子悉愿缔交推为宗伯至其造语𤣥㣲端可平揖沈谢雄视潘张惜乎长辔未骋芳兰早凋良可痛哉有诗集三巻独孤及为序今𫝊弟曾\n曽字孝常冉之弟也天宝十七年杨儇榜进士善诗出王维之门与兄名望相亚当时以比张氏景阳孟阳恊居上品载处下流侍御补阙文词亦然体制清洁华不胜文为士林所尚仕歴侍御史後坐事贬舒州司马量移阳翟令有诗一巻传于世\n独孤及〈按此𫝊有阙文考新唐书及字至之河南洛阳人〉性孝友喜鉴拔为文必彰明善恶长于议论工诗格调髙古风神迥絶得大名当时有集𫝊世\n论曰尝读选中沈谢诸公诗有题新安江水至清浅深见底贻京邑㳺好及石门新营所住四面髙山回溪石瀬修竹茂林及田南树园激流植援斋中读书南楼中望所迟客晚登三山还望京邑等数端皆竒崛精当冠絶古今曽无发其韫奥者逮盛唐沈宋独孤及李嘉佑韦应物等诸才子集中往往各有数题片言不苟皆不减其风度此则无𫝊之妙逮元和以下佳题尚罕况于诗乎立题乃诗家切要贵在卓絶清新言简而意足句之所到题必尽之中无失节外无余语此可与智者商㩁云因举而论之\n戎昱荆南人美风度能谈少举进士不第乃放逰名都虽贫士而轩昂气不消沮爱湖湘山水来客时李䕫亷察桂林寓官舍月夜闻隣居行吟之音清丽迟明访之乃昱也即延为幕宾待之甚厚崔中丞亦在湖南爱之有女国色欲以妻昱而不喜其姓戎能改则订议昱闻之以诗谢云千金未必能移姓一诺从来许杀身自谓李大夫恩私至深无任感激初事顔平原尝佐其征南幕亦累荐之卫伯玉镇荆南辟为从事歴䖍州刺史至徳中以罪谪为辰州刺史後客劔南寄家陇西数载宪宗时边烽累急大臣议和亲上曰比闻一诗人姓名稍僻者为谁宰相对以冷朝阳包子虚皆非帝举其诗对曰戎昱也上曰尝记其咏史云汉家青史上计拙是和亲社稷依明主安危托妇人岂能将玉貎便拟静沙尘地下千年骨谁为辅佐臣因笑曰魏绦何其懦也此人如在可与武陵桃花源足称其清咏士林荣之昱诗在盛唐"},{"title":"巻三","text":"钦定四库全书\n唐才子传巻三 元 辛文房 撰\n严 维 古之竒\n耿 湋 张南史\n苏 涣 吉中孚\n司空曙 李 端\n窦叔向〈子常牟羣庠巩〉 章八元\n于 鹄 冷朝阳\n李 益 畅 当\n崔 峒 夏侯审\n朱 湾 权徳舆\n武元衡 张 登\n麴信陵 姚 系〈弟伦〉\n羊士谔 杨巨源\n韩 愈〈张署〉 陈 羽\n王 涯 栁宗元\n王 建 孟 郊〈陆长源〉\n张 籍 刘 义\n李 贺\n严维字正文越州人初隠居桐庐慕子陵之高风至徳二年江淮选补使侍郎崔涣下以词藻宏丽进士及第家贫亲老不能逺离授诸暨尉时巳四十余後歴秘书郎严中丞节度河南辟佐幕府迁余姚令仕终右补阙维少无宦情懐家山之乐以儒素从升斗之禄聊代耕尔诗情雅重挹魏晋之风鍜链铿锵庶少遗恨一时名辈孰匪金兰诗集一巻今𫝊\n古之竒宝应二年礼部侍郎洪源下及第与耿湋同时尝为安西幕府书记与李司马端有金兰之好工古调足幽闲淡泊之思婉而成章得名艺圃不泛然矣诗集𫝊於世\n耿湋河东人也宝应二年洪源榜进士与古之竒为莫逆交初为大理司法充括图书使来江淮穷山水之胜仕终右拾遗诗才俊爽意思不羣似湋等軰不可多得诗集二巻今𫝊於世\n张南史字季直幽州人工奕棋神算无敌游心太极尝幅巾藜杖出入王侯之宅十年高谈濶视慷慨竒士也中歳感激始苦节学文无希世苟合之意数年间稍入诗境调体超闲情致兼美如并燕老将气韵沉雄时少及之者肃宗时庙堂奨㧞仕为左卫仓曹㕘军後避乱寓居子平难再召未及赴而卒有诗一巻今𫝊苏涣广徳二年杨栖梧榜进士少好奸利往来剽盗善用白弩巴賨商人苦之称曰白跖後自知非折节从学遂成名累迁御史湖南崔中丞瓘辟为从事瓘遇害继走交广扇动哥舒晃叛如蛟龙见血本质彰矣居无何伏诛初尝为变律诗十九首上广州节度李勉其意长於讽刺亦有陈拾遗一鳞半甲故勉加礼待之或曰此子羽翼嬖臣侵败王略今尚其文可欤勉曰汉策载蒯通説辞皇史録祖君檄草此大容细者善恶必书春秋至训言有不废孔子格谈涣其庶乎岂但存雕虫小技亦以深惩贼子耳时以为名言杜甫有与赠荅之诗今悉𫝊诗云再闻诵新作突过黄初诗今晨清镜里胜食斋房芝\n吉中孚楚州人居鄱阳最乆初为道士山阿寂寥後还俗李端赠诗云闻道华阳客儒衣谒紫微旧山连药卖孤鹤带云归栁市名犹在桃源梦已稀还家见鸥鸟应媿背船飞卢纶送诗云旧籙藏云穴新诗满帝乡来长安谒宰相有荐於天子日与王侯高㑹名动京师无几何第进士授万年尉除校书郎又登宏词科为翰林学士歴谏议大夫户部侍郎判度支事贞元初卒初拜官後以亲埀白在堂归养至孝终丧复仕中孚神骨清虚吟咏高雅若神仙中人也集一巻今𫝊\n司空曙字文初广平人也磊落有竒才韦臯节度剑南辟致幕府授洛阳主簿未几迁长林县丞累官左拾遗终水部郎中与李约员外至交性耿介不干权要家无甔石宴如也尝病中不给遣其爱姬亦尝流寓长沙迁谪江右多结契双林暗伤流景寄暕上人诗云欲就东林寄一身尚怜儿女未成人柴门客去残阳在药圃虫喧秋雨频近水方同梅市隠曝衣多笑阮家贫深山兰若何时到羡与闲云作四隣闲园即事高兴可知属调幽闲终篇调畅如新花笑日不容重染锵锵美誉不亦宜哉有诗集二巻今𫝊於世\n李端赵州人嘉佑之侄也少时居庐山依皎然读书意况清虚酷慕禅侣大歴五年李抟榜进士及第授秘省校书郎以清羸多疾辞官居终南山草堂寺未几起为杭州司马牒诉敲朴心甚厌之买田园在虎丘下为耽深僻泉石少幽移家来隠衡山自号衡岳幽人弹琴读易登高望逺神意泊然初无宦情懐箕颍之志尝曰余少尚神仙且未能去友人畅当以禅门见导余心知必是未得其门诗更高雅於才子中名响铮铮与处士京兆栁中庸大理评事江东张芬友善唱酬初来长安诗名大振时令公子郭暧尚昇平公主贤明有才延纳俊士端等皆在馆中暧尝进官大宴酒酣主属端赋诗顷刻而就曰青春都尉最风流二十功成便拜侯金距鬬鸡过上苑玉鞭骑马出长秋熏香荀令偏怜小傅粉何郎不觧愁日暮吹箫杨栁陌路人遥指鳯凰楼主甚喜一座赏叹钱起曰此必端宿制请以起姓为韵端立献一章曰方塘似镜草芊芊初月如鈎未上新开金埓看调马旧赐铜山许铸钱杨栁入楼吹玉笛芙蓉出水妬花钿今朝都尉如相顾愿脱长裾逐少年见者惊服主厚赐金帛终身以荣其工㨗类此集三巻今𫝊於世窦叔向字遗直扶风平陵人也有卓絶之行登第於大歴初逺振佳名为文物冠冕诗法谨严又非常格名流才子多仰飇尘少与常衮同灯火及衮相引擢左拾遗内供奉衮坐贬亦出为溧水令卒赠工部尚书五子常牟羣庠巩俱能诗咄咄有跨竈之誉当时美之艺文志载叔向集七巻今存诗甚寡盖零落乆矣\n常〈按此下有脱文考新唐书常字中行大歴中及进士第仕至国子祭酒〉兄弟五人聨芳比藻词价蔼然法度风流相距不逺且俱陈力王事膺宠清流岂懐玉迷津区区之比哉後人集其所着诗通一百首为五巻名窦氏聫珠集谓若五星然常集十八巻及撰韩翃至皎然三十人诗合三百五十篇为南薫集各繋以赞为三巻今并𫝊焉\n牟〈按新唐书牟字贻周〉贞元二年张正甫榜进士初学问於江东家居孝谨善事继母竒文异行闻於京师舅给事中袁高当时专重名甄㧞甚多而牟未尝干谒竟㨗文始佐六府五公八迁至检校虞部元和五年拜尚书虞部郎中转洛阳令都官郎中出为泽州刺史仕终国子司业牟晚从昭义卢从史从史寖骄牟度不可谏即移疾归居东都别业卒昌黎韩先生为墓志云\n羣〈按新唐书羣字丹列〉隠毗陵称处士性至孝定省无少怠及母卒哀痛不已啮一指置棺中结庐墓次终丧苏州刺史韦夏卿举孝亷徳宗擢为左拾遗仕至御史中丞後出为黔南观察使迁容管经畧使卒官所家无余财惟图书万轴耳\n庠〈按新唐书庠字胄卿〉尝应辟三佐大府调奉先令迁东都留守判官拜户部员外郎贞元中出为婺登二州刺史平生攻文甚苦着述亦多今并𫝊\n巩〈按新唐书巩字友封〉状貎瑰伟少博览无不通性宏放好谈古今所居多长者车辙时诸兄已逹巩尚来塲屋间颇抑初志作放鱼诗云黄金赎得免刀痕闻道禽鱼亦感恩好去长江千万里不须辛苦上龙门人知其述懐也元和二年王源中榜进士佐淄青幕府累迁秘书少监拜御史中丞仕终武昌观察副使巩平居与人言不出口时号为嗫嚅翁云\n章八元〈按新唐书艺文志注八元睦州人登大歴进士第〉初长安慈恩寺浮图前後名流诗版甚多八元亦题有云初怪鸟飞平地上自惊人语半天中後元微之白乐天至塔下遍览因悉除去惟存〈八〉元版在吟咏乆之曰名下无虚士也〈按此𫝊有阙文〉\n于鹄初买山於汉阳高隠三十犹未成名大歴中荐歴诸府从事出塞入塞驰逐风沙工诗有集今𫝊\n冷朝阳金陵人大歴四年齐映榜进士及第不待调官言归省觐自状元以下一时名士大夫及诗人李嘉佑李端韩翃钱起等大㑹赋诗攀饯以一布衣才名如此人皆羡之朝阳工诗在大歴诸才子法度稍弱字韵清越不减也有集𫝊世\n李益字君虞陇西姑臧人大歴四年齐映榜进士调郑县尉同辈行稍进逹益乆不升欝欝去游燕赵间幽州节度刘济辟为从事未几又佐邠宁幕府风流有辞藻与宗人贺相埓毎一篇就乐工赂求之被於雅乐供奉天子如征人早行篇天下皆施之绘画二十三受策秩从军十年运筹决胜尤其所长往往鞍马间为文横槊赋诗故多抑扬激厉悲离之作高适岑参之流也宪宗雅闻其名召为秘书少监集贤殿学士自负其才淩轹士衆有不能堪谏官因暴其诗不上望京楼等句以为涉怨望诏降职俄复旧除侍御史迁礼部尚书致仕太和初卒益少有僻疾多猜忌防闲妻妾过为苛酷有散灰扄户之谈时称为妒痴尚书李十郎有同姓名者为太子庶子皆在朝人恐莫辨谓君虞为文章李益庶子为门户李益云有集今𫝊\n畅当〈按唐诗纪事当河东人歴官果州刺史〉多往来嵩华间结念方外颇𠫭禅道故多松桂之兴深存不死之志词名藉甚表表凌云有诗二巻𫝊世\n崔峒博陵人工文有声初辟潞州功曹後历左拾遗终右补阙词彩炳然意思方雅时人称其句为披沙拣金往往见宝诗集一巻今行於世\n夏侯审初於华山下买田园为别墅水木幽闲云烟浩𣺌晚嵗退居其下吟讽颇多今稍零落时见一二皆锦制也\n朱湾字巨川大歴时隠君也号沧洲子率履贞素潜辉不〈翟日〉逍遥云山琴酒之间放浪形骸绳检之外郡国交徴不应工诗格体幽逺兴㑹宏深写意因时穷理尽性尤精咏物必含比兴多敏㨗之竒及李勉镇永平嘉其风操厚币邀署为府中从事日相谈讌分逾骨肉乆之尝谒湖州崔使君不得志临发以书别之曰湾闻蓬莱之山藏杳㝠而可到贵人之门无媒而通不可到骊龙之珠潜瀇滉而可识贵人之顔无因而前不可识自假道路问津主人一身孤云两度圆月载请职事三趋㦸门信知庭之与堂不啻千里向寄食漂母夜眠渔舟门如龙而难登食如玉而难得食如玉之粟登如龙之门实无机心翻成机事汉隂丈人闻之岂不大笑属谿上风便囊中金贫望甘棠而叹自引分而还湾白遂归㑹稽山隂别墅其耿介类如此也有集四巻今𫝊\n权徳舆〈按新唐书徳舆字载之〉未冠以文章称诸儒间韩洄黜陟河南辟置幕府徳宗闻其才召为太常博士改左补阙累上书直言迁起居舎人宪宗初歴兵部侍郎太子賔客陈説谋畧多中徳舆善辨论开陈古今觉悟人主为辅相尚寛不甚察察封扶风郡公有文集今𫝊\n武元衡〈按新唐书元衡字伯苍〉秉政早朝遇盗从暗中射杀之元衡工诗尝夏夜作诗曰夜乆喧暂息池台唯月明无因驻清景日出事还生翌日遇害诗盖其䜟也〈按此𫝊有阙文〉张登初隠居性刚洁幅巾短褐交友名公後就辟歴𠫭戎幕迁廷尉平乆之升监察御史贞元中改河南士曹掾迁殿中侍御史漳州刺史退居告老尝晚春乗轻车出南薫门抵暮诣宜春门入闗吏捧牌请书官位登醉题曰闲游灵沼送春回闗吏何须苦见猜八十老翁无品秩三曽身到鳯池来其狷迂如此数年坐公累被劾吏议捃摭不堪感疾而卒集六巻权徳舆为序云麴信陵贞元元年郑全济榜及第仕为舒州望江县令卒工诗有集一巻今𫝊\n姚系河中人贞元元年进士与韦应物同时有诗名工古调善弹琴好游名山希踪谢郭终身不言禄禄亦不及之也与林栖谷隠之士往还酬酢兴趣超然弟伦诗亦清丽有集并𫝊\n羊士谔贞元元年礼部侍郎鲍防下进士顺宗时累至宣歙巡官为王叔文所恶贬汀州宁化尉元和初宰相李吉甫知奨擢为监察御史掌制後以与窦羣吕温等诬论宰执出为资州刺史士谔工诗妙造梁选作皆典重早嵗尝游女几山有卜筑之志勲名相迫不遂初心有诗集行於世\n杨巨源字景山蒲中人贞元五年刘大贞下第二人及第初为张𢎞靖从事拜虞部员外郎後迁太常博士国子祭酒太和中为河中少尹入拜礼部郎中巨源才雄学富用意声律细挹得无穷之源缓隽有愈永之味长篇刻琢絶句清泠盖得於此而失于彼者矣有诗一巻行於世\n韩愈〈按愈𫝊阙〉\n论曰公英伟间生才名冠世继道徳之统明列圣之心独济狂澜词彩灿烂齐梁绮艳毫髪都捐有冠冕佩玉之气宫商金石之音为一代文宗使頽纲复振岂易言也哉固无辞足以赞述云至若歌诗累百篇而驱驾气势若掀雷走电撑决於天地之垠词锋学殖先有定价也时功曹张署亦工诗与公同为御史又同迁谪唱荅见於集中有诗赋杂文等四十巻行於世\n陈羽江东人贞元八年礼部侍郎陆贽下第二人登科与韩愈王涯等为龙虎榜後仕歴东宫卫佐羽工吟与灵一上人交游唱荅写难状之景了了目前含不尽之意皎皎言外如自遣诗云稚子新能编笋笠山妻旧觧补荷衣秋山隔岸清猿叫湖水当门白鸟飞此景何处无之前後谁能道者二十八字一片画图非造次之谓也警句甚多有集𫝊於世\n王涯〈按新唐书涯字广津〉博学工文尤多雅思举宏词宪宗时为知制诰翰林学士迁户部尚书监盐铁使涯𣙜盐苛急百姓怨之及甘露祸起就诛悉诟骂投以瓦砾须臾成堆〈按此𫝊有阙文〉\n论曰否泰姤复盈虚消息廼理之常夫物盛者衰之渐也散者积之极也有能终满而不覆者乎况图书入变化之际神物所深忌者焉前修耽玩成癖往往杀身犹非剽剥而至也王涯掊克聚敛以邀穹爵逼孤淩弱以积珍竒知己之利忘人之害至於天夺其魄鬼瞰其家一旦飘零殊可长叹孟子曰死矣盆成括𫝊曰货悖而入者亦悖而出不亦宜哉用备列之庶来者少戒云栁宗元第进士调蓝田尉累迁监察御史里行与王叔文韦执谊善二人引之谋事擢礼部员外郎欲大用值叔文败贬邵州刺史半道有诏贬永州司马遍贻朝士书言情衆忌其才无为用心者元和十年徙栁州刺史时刘禹锡同谪得播州宗元以播州非人所居且禹锡有老母具奏以栁州让禹锡而自往播㑹大臣亦有为请者遂改连州宗元在栁多惠政及卒百姓追慕立祠享祀血食至今宗元天才絶伦文章卓伟一时辈行咸仰之\n王建字仲初颍川人大歴十年丁泽榜第二人及第释褐授渭南尉调昭应县丞诸司歴荐迁太府寺丞秘书丞侍御史太和中出为陕州司马从军塞上弓剑不离身数年後归卜居咸阳原上初游韩吏部门墙为忘年之友与张籍契厚唱荅尤多工为乐府歌行格幽思逺二公之体同变时流建性耽酒放浪无拘宫词特妙前古建初与枢宻使王守澄有宗人之分守澄以弟呼之谈间故多知禁掖事作宫词百篇後因过燕饮以相讥谑守澄深衔之忽曰吾弟所作宫词内庭深邃何由知之明当奏上建作诗以谢末句云不是姓同亲向说九重争得外人知守澄恐累已事遂寝建才赡有作皆工盖尝䟦涉长途分甘穷苦其自伤诗云衰门海内几多人满眼公卿总不亲四授官资原七品再经婚娶尚单身图书亦为频移尽兄弟还因数散贫独自在家常作客黄昏哭向野田春又於征戍迁谪行旅离别幽居宦况之作俱能感动神思道人所不能道也集十巻今𫝊於世\n孟郊〈按新唐书郊字东野湖州武康人〉调溧阳尉县有投金瀬平陵城林薄蓊翳下有积水郊间往坐水傍命酒挥琴裴囘赋诗终日而曹务多废县令白府以假尉代之〈按此下有阙文〉郊卒郑余庆给钱数万营𦵏仍赡其妻子者累年张籍諡为贞曜先生门人逺赴心丧郊拙於生事一贫彻骨裘褐悬结未尝俛眉为可怜之色然好义者更遗之工诗大有理致韩吏部极称之多伤不遇年迈家空思苦竒澁读之毎令人不懽如借车载家具家具少於车如谢炭云吹霞弄日光不定暖得曲身成直身如愁人独有夜烛见一纸乡书泪滴穿如下第云弃置复弃置情如刀剑伤之类皆哀怨清切穷入㝠搜其初登第吟曰昔日龌龊不足嗟今朝旷荡恩无涯春风得意马蹄疾一日看尽长安花当时议者亦见其气度窘促卒漂沦薄宦诗䜟信有之矣天实为之谓之何哉时陆长源工诗相与来往篇什稍多亦佳作也〈按唐诗纪事长源呉人董晋帅宣武卒长源为之留後持法峭刻为军所杀〉\n张籍字文昌〈按新唐书籍和州乌江人〉贞元十五年封孟绅榜及第授秘书郎歴太祝除水部员外郎初至长安谒韩愈一㑹如平生欢才名相许论心结契愈力荐为国子博士然性狷直多所责讽於愈愈亦不忌之时朝野名士皆与游如王建贾岛于鹄孟郊诸公集中多所赠答情爱深厚皆别家千里游宦四方瘦马羸童青衫乌㡌故毎邂逅於风尘必多殷勤之思衔盃酬唱又况於同志者乎声调相似况味颇同籍於乐府古风与王司马自成机轴絶世独立自李杜之後风雅道䘮至元和中叶元白歌诗为海内宗匠谓之元和体病格稍振无愧洪河砥柱也乐天赠诗曰张公何有者业文三十春尤工乐府词举代少其伦有集七巻𫝊於世\n刘义节士也少尚义行侠傍观切齿因被酒杀人亡命㑹赦乃出更改志从学能博览为歌诗议论多出于正义刚直能靣白人长短其服义则又弥缝若亲属後以争语不能下尝持韩愈金去曰此谀墓中人所得也不若与刘君为夀遂持去客游齐鲁不知所终有诗二十七篇𫝊世\n李贺七嵗能辞章名动京师韩愈皇甫湜览其作竒之而未信曰若是古人吾曹或不知是今人岂有不识之理遂相过其家使赋诗贺总角荷衣而出欣然承命旁若无人援笔题曰高轩过二公大惊以所乘马命聫镳而还亲为束髪贺疾笃恍惚昼见人绯衣驾赤虬腾下持一版书若太古雷文曰上帝新作白玉楼成立召君作记贺叩头辞谓母老病其人曰天上比人间差乐不苦也居顷之牕中勃勃烟气闻车声甚速遂絶死时才二十七莫不怜之贺诗稍尚竒诡组织花草片片成文所得皆惊迈絶去翰墨畦迳时无能效者乐府诸诗云韶衆工皆谐之律吕尝叹曰我年二十不意一生愁心如欲谢梧桐叶矣李藩缀集其歌诗因托贺表兄访所遗失并加㸃窜付以成本弥年絶迹及诘之曰毎恨其傲忽其文已焚之矣今存十之四五杜牧为序者五巻今𫝊\n论曰老子曰其进鋭者其退速信然贺天才俊㧞弱冠而有极名天夺之速岂恡也耶若少假行年涵养盛徳观其才不在古"},{"title":"巻四","text":"钦定四库全书\n唐才子传巻四 元 辛文房 撰\n张仲素 戴叔伦\n长孙佐辅 刘言史\n李 约 张又新\n杨 衡 李 渉\n朱 昼 张 碧〈子瀛〉\n雍裕之 白居易\n元 稹 李 绅\n贾 岛 庄南杰\n鲍 溶 殷尧藩\n沈亚之 李 廓\n张 佑〈崔涯〉 熊儒登\n徐 凝 韩 琮\n韦楚老\n张仲素字绘之贞元十四年李随榜进士与李翔吕温同年以中朝无援不调潜曜乆之复中博学宏辞始任武康军从事贞元二十年迁司勲员外郎除翰林学士时宪宗求卢纶诗文遗草敕仲素编集进之後拜中书舍人仲素能属文法度严确魏文帝有云文以意为主以气为辅以词为卫此言得之矣其次词未达而意先备也善诗多警句尤精乐府往往和在宫商古人有未能虑及者集一卷及赋枢三卷今传\n戴叔伦〈按新唐书云叔伦字幼公润州金坛人〉赋性温雅善举止能清谈无贤不肖相接尽心工诗贞元十六年陈权榜进士尝在租庸幕下数年夕惕匪怠吏部尚书刘公与祠部员外郎张继书博访选材日揖宾客叔伦投刺一见称心遂就荐累迁抚州刺史政拟龚黄民乐其治圜扉寂然鞠为茂草诏书褒美封谯郡男加金紫後迁容管经畧使威名益振治亦清明仁恕多方所至称最徳宗赋中和节诗遣使者宠赐世以为荣还上表请为道士未几卒叔伦初以淮汴宼乱鱼肉江上携亲族避地来鄱阳肄业勤苦志乐清虚闭门却扫与处士张衆甫朱放素厚范张之期曽不虚月诗兴悠逺毎作惊人有述藁十巻今𫝊於世\n长孙佐辅朔方人举进士下第放懐不羁弟公辅贞元间为吉州刺史遂往依焉後卒不宦隠居以求志然风流醖藉一代名儒诗格词情繁缛不杂卓然有英迈之气毎见其拟古乐府数篇极怨慕伤感之心如水中月如镜中相言可尽而理无穷也集今𫝊\n刘言史少尚气节不举进士工诗美丽恢赡世少其伦冀镇节度使王武俊颇好词艺言史造之特加敬异武俊甞猎有双鸭起蒲稗间一矢聫之遂於马上草射鸭歌以献因表荐请官诏授枣强令辞疾不就当时重之李约字存博汧公李勉之子也元和中仕为兵部员外郎与主客员外张谂极相知毎聫枕静言逹旦不寐常赠韦况曰我有心中事不向韦郎説秋夜洛阳城明月照张八性清洁寡欲一生不近粉黛博古探竒初汧公海内名臣多蓄古今玩器约愈好之所居轩屏几案必置古铜怪石法书名画皆歴代所寳座间悉雅士清谈终日弹琴煮茗心畧不及尘事也尝使江南於海门山得双峯石及緑石琴并为好事者𫝊閟然亦寓意未尝戛然寡情豪夺恡与复嗜茶与陆羽张又新论水品特详曾授客煎茶法曰茶须暖火炙活火煎当使汤无妄沸始则鱼目散布㣲㣲有声中则四畔泉涌累累然终则腾波鼓浪水气全消此老汤之法固须活火香味俱真矣时知音者赏之有诗集後弃官终隠又着东杓引谱一巻今𫝊\n张又新〈按新唐书又新字孔昭〉善为诗恃才多轥籍其淫荡之行率见於篇尝曰我少年擅美名意不欲仕宦惟得美妻平生足矣娶杨䖍州女有徳无色殊怏怏後遇淮南李绅筵上得一歌姬与之偕老其狂斐类此性嗜茶自着煎茶水记一巻及诗文等行于世〈按新唐书又新𫝊又新初附李逢吉後附李训盖佥人也原文未载当有脱佚〉\n杨衡字仲师霅人天寳间避地西来与符载崔羣李渤同隠庐山结草堂于五老峯下号山中四友日以琴酒寓意云月遣懐衡诗工苦于声韵竒拔非常格无敢窥其涯涘常吟罢自赏其作抵掌大笑长謡曰一一鹤声飞上天谓其响彻如此人亦叹服试大理评事徃来多山僧道士为方外之期诗一巻今𫝊於世\n李渉洛阳人渤之仲兄也自号清溪子早嵗客梁园数逢兵乱避地南来乐佳山水卜隠匡卢香炉峰下石洞间尝养一白鹿甚驯狎因名所居曰白鹿洞与弟渤崔膺昆季茅舍相接後徙居终南偶从陈许辟命从事行军未几以罪谪夷陵宰十年蹭蹬峡中病疟成痼自伤羇逐头颅又复如许後遇赦得还赋诗云荷蓑不是人间事归去沧浪有钓舟遂放船重来访吴楚旧逰登天台石桥望海得风水之便挂席浮潇湘岳阳逢张祜话故因盘桓焉归洛下营草堂隠少室身自耕耘妾能织絍稚子供渔樵拓落生计伶俜酒乡罕交人事太和中宰相累荐徴起为太学博士致仕卒妻亦入道渉工为诗词意卓荦不羣世俗长篇叙事如行云流水无可牵制才名一时倾动初尝过九江𤾂口遇盗客方跧伏问何人曰李山人豪首曰若是勿用剽夺乆闻诗名愿题一篇足矣渉欣然书曰暮雨潇潇江上村緑林豪客夜知闻他时不用藏名姓世上如今半是君盗喜因以牛酒厚遗再拜送之夫以跖蹻之軰犹曰怜才而至寳横道君子不顾忍哉诗集一巻今𫝊\n朱昼广陵人〈按唐诗纪事昼元和间进士〉贞元间慕孟郊之名为诗格范相似曾不逺千里而访之不厌勤苦体尚竒澁与李渉友善相酬唱昼古镜诗云我有古时镜初自壊陵得蛟龙犹泥蟠魑魅幸月蚀磨乆见菱蕋青於蓝水色赠君将照心无使心受惑凡如此警策者颇多今𫝊於世\n张碧字太碧贞元间举进士累不第便觉三山跬歩云汉咫尺初慕李翰林之髙躅一杯一咏必见清风故其名字亦皆逼似如司马长卿希蔺相如为人也天才卓絶气韵不凡委兴山水投闲吟酌言多野意俱状难摹之景焉有歌行集二巻𫝊世子瀛\n瀛碧之子也仕广南刘氏官至曹郎甞为诗赠琴棋僧云我尝聴师法一説波上莲花水中月不垢不浄是色空无法无空亦无灭我尝对师禅一观浪溢鳌头蟾魄满河沙世界尽空空一寸寒灰冷灯畔我又闻师琴一抚长松唤住秋山雨中雅㺯若铿金指下寒泉流太古我又看师碁一着山顶坐沉红日脚阿谁称是国手人罗浮道士赌却鹤输却药葫芦斟下红霞丹束手不敢争头角同列见之曰非其父不生是子瀛为诗尚气而不怒号语新意卓人所不思者辄能道之绰绰然见乃父风也有诗集今𫝊於世\n雍裕之蜀人有诗名贞元後数举进士不第飘蓬四方为乐府极有情致集一巻今𫝊\n白居易〈按新唐书云居易字乐天其先太原人又徙下邽〉弱冠名未振观光上国谒顾况况吴人恃才少所推可因谑之曰长安百物皆贵居大不易及览诗巻至离离原上草一嵗一枯荣野火烧不尽春风吹又生乃叹曰有句如此居天下不难老夫前言戏之耳居易厯左拾遗时盗杀宰相京师汹汹居易上䟽请亟捕贼权臣有嫌其出位怒之俄有言居易母堕井死而赋新井篇言既浮华行不可用贬江州司马初来九江居庐阜峯下作草堂烧丹欲自除其病後以忠鲠遭摈仕情顿尔索寞卜居履道里与香山僧如满等种树构石楼凿八节滩为㳺赏之乐茶铛酒杓不相离科头箕踞谈禅咏古晏如也晚节好佛经月不荤称香山居士〈按居易传有脱文今就永乐大典所载五条编録〉\n元稹河南人九嵗工属文十五擢眀经对䇿第一拜左拾遗上书言利害当路恶之後拜监察御史按狱东川还次敷水驿中人仇士良夜至稹不譲邸仇怒击稹败面宰相以稹年少威轻失宪臣体贬江陵士曹参军〈按元稹𫝊有阙文〉\n李绅〈按新唐书绅字公垂〉拜中书侍郎为人短小精悍於诗特有名号短李〈按绅传阙祗存此三语〉\n贾岛字浪仙范阳人也初连败文塲囊箧空甚遂为浮屠名无本来东都旋往京师居青龙寺时禁僧午後不出为诗自伤元和中元白变尚轻浅岛独按格入僻以矫浮艳当㝠搜之际前有王公贵人皆不觉逰心万仞虑入无穷自称碣石山人甞叹曰知余素心者惟终南紫阁白阁诸峯隠者耳嵩丘有草庐欲归未得逗留长安虽行坐寝食苦吟不辍尝跨蹇驴张盖横截天衢时秋风正厉黄叶可扫遂吟曰落叶满长安方思属聫杳不可得忽以秋风吹渭水为对喜不自胜因唐突大京兆刘栖楚被系一夕旦释之後复乗闲䇿蹇访李凝幽居得句云鸟宿池邉树僧推月下门又欲作僧敲练之未定吟哦引手作推敲之势傍观亦讶时韩退之尹京兆车骑方出不觉冲至第三节左右拥到马前岛具实对未定推敲神逰象外不知回避韩驻马久之曰敲字佳遂并辔归共论诗道结为布衣交遂授以文法去浮屠举进士愈赠诗云孟郊死𦵏北邙山日月风云顿觉闲天恐文章浑断絶再生贾岛在人间自此名着时新及第寓居法乾无可精舍姚合王建张籍雍陶皆琴樽之好一日宣宗㣲行至寺闻钟楼上有吟声遂登焉于岛案取卷览之岛不识因作色攘臂睨而夺取之曰郎君鲜醲自足何㑹此也帝下楼去既而觉之大恐伏阙待罪上讶之他日有中旨令与一清官谪去主者乃授遂州长江主簿後稍迁晋州司仓临死之日家无一钱惟病驴古琴而已当时谁不爱其才而惜其命薄岛貌清意雅好谈禅宗𤣥理所交悉尘外之人况味萧条生计岨峿自题曰二句三年得一吟双泪流知音如不赏归卧故山秋毎至除夕必取一嵗所作置几上焚香再拜酹酒祝曰此吾终年苦心也痛饮长謡而罢今集十巻并诗格一巻𫝊于世\n庄南杰与贾岛同时曾从受学工乐府杂歌诗体似长吉气虽壮遒语过镌凿盖其天资本劣未免按抑不出自然亦一好竒尚僻之士耳集二巻今行\n鲍溶字徳源元和四年韦瓘榜进士在杨汝士一时与李端公益少同袍为尔汝交初隠江南山中避地家苦贫劲气不扰羇旅四方登临懐昔皆古今絶唱过陇头古天山大坂泉水呜咽分流四下赋诗曰陇头水千古不堪闻生归苏属国死别李将军细响风凋草清哀鴈入云其警絶大槩如此古诗乐府可称独歩盖其气力宏赡博识清度雅正髙古衆才无不备具云卒飘蓬薄宦客死三川有集五巻今𫝊\n殷尧藩秀州人天性简静眉目如画工诗文耽丘壑之趣尝曰吾一日不见山水与俗人谈便觉胷次尘土堆积急呼浊醪浇之聊解秽耳元和九年韦贯之放榜尧藩落第杨尚书大为称屈料理因擢进士数年为永乐县令一舸之官弹琴不下堂而人不忍欺雍陶寄诗曰古县萧条秋景晚昔时陶令亦如君头巾漉酒临黄菊手板支頥向白云百里岂能容骥足九霄终自别鸡羣相思不恨书来少佳句多从阙下闻与沈亚之马戴为诗友赠答甚多後仕终侍御史尧藩初逰韦应物门墙分契莫逆及来长沙尚书李翺席上有舞柘枝者容语凄恻因感而赋诗以赠曰姑苏太守青娥女流落长沙舞柘枝满座绣衣皆不识可怜红粉泪双埀衆客惊问之果韦公爱姬所生女也相与吁叹翺即命削丹书於宾馆中择士嫁之今有集一巻𫝊世皆铿锵藴藉之作也\n沈亚之字下贤吴兴人初至长安与李贺结交举进士不第为歌以送归元和十年侍郎崔羣下进士泾原李彚辟为掌书记迁秘书省正字长庆中补栎阳令四年迁福建团练副使事徐晦後累迁殿中丞御史内供奉太和三年栢耆宣慰徳州取为判官耆罢亚之贬南康尉後终郢州掾亚之以文词得名然狂躁贪冒辅耆为恶颇慿陵晚逹故及于谪常逰韩吏部门杜牧李商隠俱有拟沈下贤诗盖甚为当时名辈器重云有集九巻𫝊世\n李廓宰相程之子也少有志勲业揽辔慨然而未肯屑就遂困塲屋中作下第诗曰榜前潜制泪衆里独嫌身气味如中酒情懐似别人时流皆称赏且怜之因共推挽元和十三年独孤樟榜进士调司经局正字出为鄠县令累厯显宦仕终武寜节度使政有竒绩〈按新唐书廓为武寜节度不能治军为军所逐原文所云非事实也〉工诗极绮致与贾岛友善集今传张佑字承吉南阳人来寓姑苏乐髙尚称处士骚情雅思凡知己者悉当时英杰然不业程文元和长庆间深为令狐文公器许镇天平日自草表荐以诗三百首献于朝辞畧曰凡制五言苞含六义近多放诞靡有宗师祜乆在江湖早工篇什研几甚苦捜象颇深辈流所推风格罕及谨今缮录诣光顺门进献望宣付中书门下祜至京师属元稹号有城府偃仰内廷上因召问祜之词藻上下稹曰张祜雕虫小巧壮夫不为若奬激太过恐变陛下风教上颔之由是寂寞而归为诗自悼云贺知章口徒劳説孟浩然身更不疑遂客淮南杜牧时为度支使极相善待有赠云何人得似张公子千首诗轻万户侯祜苦吟妻孥每唤之皆不应曰吾方口吻生花岂恤汝辈乎性爱山水多逰名寺如杭之灵隠天竺苏之灵岩楞伽常之惠山善权润之甘露招隠往往题咏唱絶同时崔涯亦工诗与佑齐名颇自放行乐或乗兴北里毎题诗倡肆誉之则声价顿増毁之则车马扫迹涯尚义有侠诗云太行岭上三尺雪崔涯袖中三尺鐡一朝若遇有心人出门便与妻儿别尝共谒淮南李相祜称钓鳌客李怪之曰钓鳌以何为竿曰以虹以何为鈎曰新月以何为饵曰以短李相公也绅壮之厚赠而去晚与白乐天日相聚讌谑乐天讥以足下新作忆柘枝云鸳鸯钿带抛何处孔雀罗衫付阿谁乃欵头诗耳祜曰鄙薄之诮是也君明皇长恨歌曰上穷碧落下黄泉两处茫茫都不见又非目连寻母邪一座大笑初过广陵题曰十里长街市井连月明桥上看神仙人生只合扬州死禅智山光好墓田大中中果卒於丹阳隠居人以为䜟云诗一巻今𫝊\n论曰卫蘧伯玉耻独为君子令狐公其庶几元稹则不然矣十誉不足一毁有余其事业浅深于此可以观人也尔所不知人其舍诸稹谓佑雕虫璅璅而稹所为有不若是耶忌贤嫉能迎户而噬畧已而过人者穿窬之行也祜能以处士自终其身声华不借钟鼎而髙视当代至今称之不遇者天也不泯者亦天也岂若取容阿附遗臭之不已者哉\n熊儒登锺陵人有诗名元和中为西川从事与白舍人钊善多赠答亦祗役湘中数年凡下笔言语妙天下如江流如箭月如弓行尽三湘数夜中无奈子规知向蜀一声声似怨春风又经古墓云碑折松枯山火烧夜台曽闭不曽朝那将逝者比流水流水东流逢上潮类此极多有集今𫝊\n徐凝〈按唐诗纪事凝睦州人〉有诗名无进取之意始逰长安不忍自衒鬻竟不成名将归以诗辞韩吏部云一生所遇惟元白天下无人重布衣欲别朱门泪先尽白头逰子白身归〈按此𫝊有阙文〉\n韩琮字成封长庆四年李郡榜进士後大中中仕至湖南观察使有诗名多清新之制锦绮不如也滻水送别云緑暗红稀出鳯城暮云楼阁古今情行人莫聴宫前水流尽年光是此声骆谷晚望云秦州如画渭如丝去国还家一望时公子王孙莫来好岭花多是断肠枝如此等皆喧满人口余极多皆称是集一巻今𫝊\n韦楚老〈按唐诗纪事楚老长庆进士〉工诗气既沈雄语亦豪健作祖龙吟曰黒云兵气射天裂壮士朝眠梦寃结祖龙一夜死沙丘胡亥空随鲍鱼辙腐肉偷生二千里伪书先赐扶苏死墓接骊山土未乾瑞光已向芒砀起陈胜城中鼔三下秦家天地如崩瓦龙蛇撩乱入咸阳"},{"title":"巻五","text":"钦定四库全书\n唐才子传巻五 元 辛文房 撰\n杜 牧〈严恽 子荀鹤张曙〉杨 发\n李 逺 许 浑\n雍 陶 贾 驰\n李商隠 温庭筠〈纪唐夫子宪〉\n刘得仁 薛 逢\n赵 嘏 李宣古〈弟宣逺〉\n姚 鹄 项 斯\n马 戴 孟 迟\n薛 能 任 蕃\n杜牧字牧之京兆人也善属文太和二年韦筹榜进士与厉𤣥同年初未第来东都时主司为侍郎崔郾太学博士吴武陵䇿蹇进谒曰侍郎以峻徳伟望为明君选才仆敢不薄施尘露向偶见文士十数辈眉抵掌共读一巻文书览之乃进士杜牧阿房宫赋其人王佐才也因出巻搢笏朗诵之郾大加赏曰请公与状头郾曰已得人矣曰不得即请第五人更否则请以赋见还辞容激厉郾曰诸生多言牧踈旷不拘细行然敬依所教不敢易也後又举贤良方正科後人评牧诗如铜丸走坂骏马注坡谓圆快奋急也牧美容姿好歌舞风情颇张不能自遏〈按此处有阙文〉时淮南称繁盛不减京华且多名姬絶色牧恣心逰赏牛相收街吏报杜书记平安帖子至盈箧後以御史分司洛阳时李司徒闲居家妓为当时第一宴朝士以牧风宪不敢邀牧因遣讽李使召已既至曰闻有紫云者妙歌舞孰是即赠诗曰华堂今日绮筵开谁唤分司御史来忽发狂言惊四座两行红粉一时囬意气闲逸傍若无人座客莫不称异太和末往湖州近城一女子方十余嵗约以十年後吾来典郡当纳之结以金币洎周墀入相牧上笺乞守湖州比至已十四年前女子从人两抱雏矣赋诗曰自恨寻芳去较迟不须惆怅怨芳时如今风摆花狼籍緑叶成隂子满枝此其大槩如此凡所牵系情见乎辞别业在樊川有樊川集二十巻及注孙子并𫝊同时有严恽字子重工诗与牧友善以问春诗得名昔闻有集今无之矣牧子荀鹤荀鹤字彦之牧之㣲子也牧㑹昌末自齐安移守秋浦时妾有娠出嫁长林乡正杜筠生荀鹤早着诗名尝谒梁王朱全忠与之坐忽无云而雨王以为天泣不祥命作诗称意王喜之荀鹤寒畯连败文场甚苦至是遣送名春官大顺二年裴䞇侍郎下第八人登科正月十日放榜正荀鹤生朝也王希羽献诗曰金榜晓悬生世日玉书潜记上昇时九华山色髙千尺未必髙於第八枝荀鹤居九华峯号九华山人张曙拾遗亦工诗又同年尝醉谑曰杜十五大荣而得与曙同年荀鹤曰是公荣天下只知有荀鹤若个知有张五十郎邪各大笑而罢宣州田頵甚重之常致笺问梁王立荐为翰林学士迁主客员外郎颇恃势侮慢缙绅为文多主箴刺衆怒欲杀之未得天佑元年卒荀鹤苦吟平生所志不遂晚始成名况丁乱世殊多忧惋思虑之语於一觞一咏变俗为雅极事物之情足丘壑之趣非易能及者也与太常博士顾云初隠一山登第之明年寜亲相㑹云撰集其诗三百余篇为唐风集三卷且序以为壮语大言则决起逸发可以左揽工部袂右拍翰林肩吞贾喻八九於胷中曽不芥蔕或情发乎中则极思㝠搜神逰希夷形兀枯木五声劳於呼吸万象贫于抉剔信诗家之雄杰者矣荀鹤嗜酒善弹琴风情雅度千载犹可想望也杨发太和四年礼部侍郎郑澣下第二人及第工诗亦当时声韵之伟者畧举一篇宿黄花馆云孤馆萧条槐叶稀暮蝉声隔水声㣲年年为客路长在日日送人身未归何处离鸿迷浦月谁家愁妇捣寒衣夜深不卧帘犹卷数㸃残萤入户飞俱浏亮清新颇惊凡听恨其出处事迹不得而知也有诗𫝊世尚多\n论曰礼乐之学何世无之周罗㬋虎将也而能不失事旧主之仪杨发健吏也而能抗改作神主之议杨收博学精辨其议音律之变与旗常之藏诚不谬於古然运丁叔季制行出处皆不能尽合中道位愈髙则祸愈大古称知礼乐之情者能作知礼乐之文者能述夫皆知礼乐之文者欤\n李逺〈按唐诗纪事逺字宣古〉太和五年杜陟榜进士及第蜀人也少有大志逺迈流俗为诗多逸气五彩成文早厯下邑词名卓然宣宗时宰相令狐綯进奏拟逺杭州刺史上曰朕闻逺诗有青山不厌千杯酒白日惟销一局棊是踈放如此岂可临郡理人綯曰诗人托此以写髙兴耳未必实然上曰且令往观之至果有治声性简俭嗜啗鳬鸭贵客经过无他赠厚者緑头一双而已後厯忠建江三州刺史仕终御史中丞初牧湓城求天寳遗物得秦僧収杨妃袜一裲珍袭呈诸好事者㑹李羣玉校书自湖湘来过九江逺厚遇之谈笑永日羣玉话及向赋黄陵庙诗动朝云暮雨之兴殊亦可怪逺曰仆自获凌波片玉软轻香窄毎日一见未尝不在马嵬下也遂更相戏笑各有赋诗後来颇为法家所短盖多情少束亦徒以㣲辞相感动耳有诗集一巻今𫝊\n许浑字仲晦润州丹阳人圉师之後也太和六年李珪榜进士为当涂太平二县令少苦学劳心有清羸之疾至是以伏枕免乆之起为润州司马大中三年拜监察御史厯虞部员外郎睦郢二州刺史尝分司朱方买田筑室後抱病退居丁夘涧桥村舍暇日缀录所作因以名集浑乐林泉亦慷慨悲歌之士登髙懐古已见壮心故其格调豪丽犹强弩初张牙浅急惧无留意耳至今慕者极多家家自谓得骊龙之照夜也早嵗尝逰天台仰看瀑布旁眺赤城辨方广于非烟蹑石桥于悬壁登陟兼晨穷览幽胜朗诵孙绰古赋傲然有思归之想志存不朽再三信宿旁徨不能去以王事不果有负初心後昼梦登山有宫阙淩虚问曰此崑仑也少顷逺见数人方饮招浑就坐暮而罢一佳人出笺求诗未成梦破後吟曰晓入瑶台露气清庭中惟见许飞琼尘心未断俗縁在十里下山空月明他日复梦至山中佳人曰子何题余姓名於人间遂改为天风吹下歩虚声曰善矣浑才思翩翩仙子所爱梦寐求之一至於此昔子建赋洛神人以徒闻虚语以是为迂诞不信矣未几遂卒有诗三巻今𫝊\n雍陶字国钧成都人工于词赋少贫遭蜀中乱後播越羇旅有诗云贫当多病日闲过少年时太和八年陈寛榜进士及第一时名辈咸伟其作然恃才傲睨薄於亲党其舅云安刘钦之下第归三峡却寄陶诗云地近衡阳虽少鴈水连巴蜀岂无鱼陶得诗颇愧赧遂通问不絶大中六年授国子毛诗博士与贾岛殷尧藩无可徐凝章孝标友善以琴樽诗翰相娱留长安中大中末出刺简州时名益重自比谢宣城栁吴兴国初诸人诗奴耳宾至必佯狂挫辱投贽者少得通秀才冯道明时称机㨗因罢举请谒绐阍者曰与太守有故陶倒屣及见呵责曰与足下素昧平生何故之有冯曰诵公诗文室迩人逺何隔平生吟陶诗数聫如立当青草人先见行近白莲鱼未知又闲门客到常如病满院花开未是贫又江声秋入峡雨色夜侵楼等句陶多其慕已厚赠遣之自负如此後为雅州刺史郭外有情尽桥乃分衿祖别之所因送客陶怪之遂於上立候馆改名折栁桥取古乐府折杨栁之义题诗曰从来只有情难尽何事呼为情尽桥自此改名为折栁任地离恨一条条甚脍炙当时竟辞荣闲居庐岳养疴傲世与尘事日冥矣贾驰太和九年郑确榜进士初负才质蹭蹬名塲往来公卿间担簦蹑屩莫伸其志尝入关赋诗云河上㣲风来闗头树初湿今朝闗城吏又见孤客入上国谁与期西来徒自急主司闻之颇有怜才之意遂放第不甚显宦诗文俱得美声後来文士集中多称贾先軰其名誉为时所重云有集𫝊世\n李商隠字义山〈按新旧唐书商隠懐州河内人〉令狐楚竒其才使逰门下授以文法遇之甚厚开成二年髙锴知贡举楚善於锴奬誉甚力遂擢进士又中㧞萃楚又奏为集贤校理楚出王茂元镇河阳素爱其才表掌书记以子妻之除侍御史茂元为李徳裕党士流嗤谪商隠以为诡薄无行共排摈之来京师乆不调更依桂林总管郑亚府为判官後随亚谪循州三年始囘〈按商隠樊南乙集自序云余为桂林从事日常使南郡明年正月自南郡归二月府贬选为盩厔尉尹即留假参军事典章奏考商隠自岭表归朝即为京兆尹卢𢎞正掾曺其在岭表朞年耳原文及新旧唐书并误〉归穷於宰相綯綯恶其忘家恩放利偷合从小人之辟谢絶殊不展分重阳日因诣㕔事留题云十年泉下无消息九日樽前有所思又云郎君官贵施行马东阁无因许再窥綯见之恻然乃补太学博士栁仲郢节度东川辟为判官商隠亷介可畏出为广州都督人或袖金以赠商隠曰吾自性分不可易非畏人知也未几入拜检校吏部员外郎罢客荥阳卒〈按新唐书栁仲郢节度劒南东川辟商隠为判官检校工部员外郎府罢客荥阳卒则员外郎系判官带䘖并非入拜亦非吏部也又商隠亦未为广州都督原文全误〉商隠工诗为文瑰迈竒古辞难事隠及从楚学俪偶长短而繁缛过之毎属缀多检閲书册左右鳞次号獭祭鱼而㫖能感人人谓其横絶前後时温庭筠段成式各以穠致相夸号三十六体後评者谓其诗如百寳流苏千丝铁网绮宻妍要非适用之具斯言信哉初得大名薄逰长安尚希识面因投宿逆旅有衆客方酣饮赋木兰花诗就呼与坐不知为商隠也後成一篇云洞庭波冷晓侵云日日征帆送逺人几度木兰船上望不知原是此花身客问姓名大惊称罪时白乐天老退极喜商隠文章曰我死後得为尔儿足矣白死数年生子遂以白老名之既长殊鄙钝温飞卿戏曰以尔为侍郎後身不亦忝乎後更生子名衮师聪俊商隠诗云衮师我娇儿英秀乃无匹此或其後身也商隠文自成一格後学者重之谓西崑体也有樊南甲集二十巻乙集二十巻玉溪生诗三卷初自号玉溪子又赋一巻文一巻并𫝊於世\n温庭筠字飞卿旧名岐并州人宰相彦博之孙也少敏悟天才雄赡能走笔万言善鼓琴吹笛云有即弹有孔即吹何必爨桐与柯亭也侧词艳曲与李商隠齐名时号温李才情绮丽尤工律赋毎试押官韵烛下未尝起草但笼袖慿几毎一韵一吟而已塲中曰温八吟又谓八义手成八韵名温八义多为邻铺假手然薄行无检幅与贵胄裴诚令狐滈等饮博後中夜醉诟狭斜间为逻卒折齿诉不得理举进士数上又不第出入令狐相国书馆中待遇甚优时宣宗喜歌菩萨蛮綯假其新撰进之戒令勿泄而遽言於人綯又尝问玉条脱事对以出南华经且曰非僻书相公燮理之暇亦宜览古又有言曰中书省内坐将军讥綯无学由是渐踈之自伤云因知此恨人多积悔读南华第二篇徐商镇襄阳辟巡官不得志逰江东大中末山北沈侍郎主文特诏庭筠试於帘下恐其潜救是日不乐逼暮先请出仍献启千余言询之已占授八人矣执政鄙其所为留长安中待除宣宗㣲行遇於传舍庭筠不识傲然诘之曰公非司马长史之流乎又曰得非六参簿尉之类帝曰非也後谪方城尉中书舍人裴坦当制忸怩含毫乆之词曰孔门以徳行居先文章为末尔既早随计吏宿负雄名徒夸不羁之才罕有适时之用放骚人於湘浦移贾谊於长沙尚有前席之期未爽抽毫之思庭筠之官文士诗人争赋诗祖饯惟纪唐夫擅场曰鳯凰诏下虽沾命鹦鹉才髙却累身唐夫举进士有词名庭筠仕终国子助教竟流落而死今有汉南真藁十巻握兰集三巻金筌集十巻诗集五巻及学海三十巻又采茶录一巻及着乾𦠆子一巻序云不爵不觥非炰非炙能説诸心庶乎乾𦠆之义并𫝊於世子宪\n宪庭筠之子也龙纪元年李瀚榜进士及第去为山南节度府从事大着诗名词人李巨川草荐表盛述宪先人之屈其畧曰蛾眉先妬明妃为去国之人猿臂自伤李广乃不侯之将上读表恻然称美时宰臣亦有知者曰父以窜死今孽子宜稍振之以厌公议庶几少雪忌才之恨上颔之後迁至郎中卒有集文赋等𫝊於世刘得仁出入举二十年竟无所成投迹幽隠未尝耿耿有寄所知诗云外族帝皇是中朝亲故稀翻令浮议者不许九霄飞忧而不困怨而不怒哀而不伤铿锵金玉难合同流而不厌于磨淬端能确守格律揣治声病甘心穷苦不汲汲于富贵王孙公子中千载求一人不可得也\n薛逢〈按旧唐书逢字陶臣河东人书录觧题逢㑹昌元年进士〉晚年岨峿宦途尝䇿羸赴朝值新进士榜下缀行而出呵殿赫然见逢行李萧条前导曰逥避新郎君逢冁然因遣一介语之曰报道莫贫相阿婆三五少年时也曾东涂西抺来其人辟易〈案此𫝊有阙文〉\n论曰逢天资本髙学力亦赡故不甚苦思而自有豪逸之态第长短皆率然而成未免失浅露俗盖亦当时所尚非离羣絶俗之诣也夫道家三寳其一不敢为天下先前人者孰肯後之加人者孰能受之观逢恃才怠傲耻在喧卑而喋喋唇齿亦犹恶醉而强酒也累摈逺方寸进尺退至龙锺而自愤不已盖祸福无不自已者焉有诗集十巻又别纸十三巻赋集十四巻今并行赵嘏字承佑山阳人㑹昌二年郑言榜进士大中中仕为渭南尉一时名士大夫极称道之卑宦不如意宣宗雅知其名因问宰相赵嘏诗人曾为好官否可取其诗进来读其巻首题秦诗云徒知六国随斤斧莫有羣儒定是非上不悦事寝嘏尝秋晚赋诗曰残星几㸃鴈横塞长笛一声人倚楼杜牧之呼为赵倚楼赏叹之也又初有诗落句云早晚粗酬身事了水邉归去一闲人仕涂𣕕杌岂其䜟也嘏豪迈爽逹多陪接卿相出入馆阁如亲属然能以书生令逺近知重所谓一夕名动京师三日𫝊满天下有自来矣命沾僊尉追踪梅市亦不恶耳先嘏家浙西有美姬溺爱及计偕留侍母㑹中元㳺鹤林寺浙帅窥见悦之夺归明年嘏及第自伤赋诗曰寂寞堂前日又曛阳台去作不归云当时闻説沙吒利今日青娥属使君帅闻之殊惨惨遣介送姬入长安时嘏方出闗途次横水驿於马上相遇姬因抱嘏痛哭信宿而卒遂葬于横水之阳嘏思慕不已临终日有所见时方四十余今有渭南集及编年诗二巻悉取十三代史事迹自始生至百嵗嵗赋一首二首总得一百一十章今并行于世\n李宣古字埀後澧阳人㑹昌三年卢肇榜进士又试中宏辞工文极俊有诗名性谑浪多所讥诮时杜悰尚主出守澧阳宣古在馆下数陪宴赏谐慢既深悰不能忍忿其戏巳辱之使卧泥中衣冠颠倒岐阳公主素惜其才劝曰尚书独不念诸郎学文待士如此那得平阳之誉乎遣人扶起更以新服赴中座使宣古赋诗谢曰红灯初上月轮髙照见堂前万朶桃觱栗调清银象管琵琶声亮紫檀槽能歌姹女顔如玉解饮萧郎眼似刀争奈夜深抛要令舞来挼去使人劳杜公赏之後悰二子裔休儒休皆中第人曰非母贤待师不足成其子今诸集中往往载其作有英气调颇清丽惜不多见竟薄命无组绶之誉落寞自终弟宣逺亦以诗名今传者可数也姚鹄字居云㑹昌三年礼部尚书王起下进士多出入当时好士公卿之席幕然吏才文价俱不甚超一名仅尔流播亦多幸矣诗一巻今𫝊\n项斯字子迁江南人也㑹昌四年王起下第二人进士官润州丹徒县尉卒於任所开成之际声价藉甚特为张水部所知赏故其诗格颇与水部相类清妙竒絶郑少师薰赠诗云项斯逢水部谁道不闗情斯性踈旷温饱非其本心初筑草庐于朝阳峯前交结静者盘薄岩林戴藓花冠披鹤氅就松隂枕白石饮清泉长哦细酌凡如此三十余年晚污一名殊屈清致其警聫如病尝山药徧贫起草堂低如客来因月宿床势向山移下第云独存过江马强拂看花衣病僧云不言身後事犹坐病中禅又湖山万叠翠门树一行春又一灯愁里梦九陌病中春又如月明古寺客初到风度闲门僧未归又宫人入道云将敲碧落新齐磬却进昭阳旧赐筝之类不一而足当时盛称杨敬之祭酒赠诗云几度见君诗总好及观标格过于诗平生不解藏人善到处逢人説项斯其名以此益彰矣集一巻今行\n马戴〈按新唐书艺文志注云戴字虞臣唐诗纪事云戴㑹昌五年进士〉苦家贫禄仕代耕嵗廪殊薄然终日吟事清虚自如秋思一絶曰万木秋霖後孤山夕照余田园无嵗计寒近忆樵渔〈按此条有阙文〉孟迟字逹之平昌人㑹昌五年易重榜进士有诗名尤工絶句风流妩媚皆宫商金石之声与顾非熊甚相得且同年有诗一巻行于世\n薛能字太拙汾州人㑹昌六年狄慎思榜登第大中末书判入等中选补盩厔尉辟太原陕虢河阳从事李福镇滑台表为观察判官歴侍御史都官刑部员外郎福徙帅西蜀奏以自副咸通中摄嘉州刺史造朝迁主客度支刑部郎中俄为同州刺史京兆大尹出帅感化入授工部尚书复节度徐州徙镇忠武广明元年徐军戍溵水经许能以军多懐旧惠馆待于城中许军惧见袭大将周岌乗衆疑怒因为乱逐能据城自称留後数日杀能并屠其家能治政严察絶请谒耽癖於诗日赋一章为课性喜淩人格律卑卑亦无甚髙论尝以第一流自居罕所㧞拂时刘得仁擅雅称持诗巻造能能以句谢云千首如一首巻初如巻终盖讥其无变体也量人如此非厚徳君子晚节尚浮屠奉法唯谨资性傲忽又多佻轻忤世及为藩镇毎易武吏尝命其子属櫜鞬雅拜新进士或问其故曰渠消弭灾咎耳今有集十巻及繁城集一巻𫝊焉\n任蕃㑹昌间人家江东多逰㑹稽苕霅间初亦举进士之京不第榜罢进谒主司曰仆本寒乡之人不逺万里手遮赤日歩来长安取一第荣父母不得侍郎岂不闻江东一任蕃家贫吟苦忍令其去如来日也敢从此辞弹琴自娱学道自乐耳主司惭欲留不可得归江湖专尚声调去逰天台巾子峯题寺壁间云絶顶新秋生夜凉鹤翻松露滴衣裳前峯月照一江水僧在翠㣲开竹房既去百余里欲囘改作半江水行至题处他人已改矣後复有题诗者亡其姓名曰任蕃题後无人继寂寞空山二百年才名类是凡作必使人改视易聴如洛阳道云憧憧洛阳道尘下生春草行者岂无家无人在家老鸡鸣前结束争去恐不早百年路傍尽白日车中晓求富江海狭取贵山岳小热中赴长途奔走何由了想蕃风度此亦足举其梗槩有诗七十七首"},{"title":"巻六","text":"钦定四库全书\n唐才子传巻六 元 辛文房 撰\n曹 邺 郑 嵎\n刘 驾 李 频\n李羣玉 李 郢\n储嗣宗 曹 唐\n郑 巢 于武陵\n高 骈 李昌符\n汪 遵 翁 绶\n沈 光 邵 谒\n司空图 崔道融\n聂夷中 许 棠\n周 繇〈张演〉 皮日休\n郑 谷 张 乔\n胡 曾 来 鹏\n李山甫 赵光远〈卢弼〉\n赵 牧〈刘光远〉 牛 峤\n曹邺字业之桂林人累举不第为四怨三愁五情诗雅道甚古特为舍人韦慤所知力荐於礼部侍郎裴休大中四年张温琪榜中第看榜日上主司诗云一辞桂岩猿九泣都门月年年孟春至看花如看雪杏园宴间呈同年云岐路不在天十年行不至一旦公道开青云在平地又云忽忽出九衢童仆颜色异故衣未及换尚有去年泪又云永持共济心莫起胡越意佳句类此甚多志特勤苦仕至洋州刺史有集一卷今传\n郑嵎字宾光大中五年李郜榜进士有集一卷名津阳门诗津阳即华清宫之外阙询求父老为诗百韵皆纪明皇时事者也\n刘驾〈按书录解题驾字司南〉与曹邺为友深相结邺既擢第不忍先归待长安中驾成名〈按书录解题驾大中六年进士〉乃同归彭蠡故山时国家复河湟故地有归马放牛之象驾献乐府十章上深悦累歴达官\n李频〈按新唐书频字徳新睦州夀昌人大中八年擢进士第〉工诗与同里方干为师友给事中姚合时称诗颖频不惮走千里丐其品第合见大加奬挹且爱其标格即以女妻之〈按此传有阙文〉李羣玉字文山澧州人也清才旷逸不乐仕进专以吟咏自适诗笔遒丽文体丰美好吹笙美翰墨如王谢子弟别有一种风流亲友强之赴举一上即止裴相公休观察湖南厚礼延致之郡中尝勉之曰处士被褐懐玉浮云富贵名高而身不知神寳宁久弃荒途子其行矣大中八年以草泽臣来京诣阙上表自进诗三百篇休适入相复论荐上悦之勅授𢎞文馆校书郎李频使君呼为从兄归湘中题诗二妃庙是暮宿山舍梦见二女子来曰儿娥皇女英也承君佳句徽佩将游於汗漫愿相从也俄而影灭羣玉自是郁郁岁余而卒段成式为诗哭曰曾话黄陵事今为白日催老无男女累谁哭到泉台今有诗三卷後集五巻行世\n论曰夫澧浦古骚人之国屈原仕遭谮毁不知所诉心烦意乱赋为离骚盖言离愁也国人莫知我兮又何怀乎故都委身鱼腹魂招不来芳草遽萎萧艾参天奚独一时而然也羣玉继禀修能翺翔大化人不知而不愠禄不及而不言望涔阳之亡极挹桂兰之绪馨欵君门以披懐沾一命而潜退风景满目宁无愧於古人故其格调清越而多登山临水懐人送归之制如逺客坐长夜雨声孤寺秋请量东海水看取浅深愁等句已曲尽羇旅坎𡒄之情壮心千里於方寸不扰焉亦云难矣李郢字楚望大中十年崔鉶榜进士及第初居余杭出有山水之兴入有琴书之娯疏於驰竞歴为藩鎭从事後拜侍御史郢工诗理密辞娴个个珠玉其清丽极能写景状懐毎使人竟日不能释卷与清塞贾岛最相善时塞还俗岛亦寻卒郢重来钱塘俱絶音响感而赋诗曰却到城中事事伤惠休归俗贾生亡谁人收得文章箧独我重经苔藓房一命未沾为逐客万缘初尽别空王萧萧竹坞残阳在叶覆闲阶雪拥墙其他警策率类此有集一卷今传\n储嗣宗大中十三年孔纬榜及第与顾非熊先生相结好大得诗名苦思梦索所谓逐句留心每字着意悠然尘外之想览其所作及见其人警聨如绿毛辞世女白髪入壶翁又片水明在野万花深见人又黄鹤有归语白云无忌心又蝉鸣月中树风落客前花又池亭千里月烟水一封书又鹤语松上月花明云里春又一酌水边酒数声花下琴又宿草风悲夜荒村月吊人哭彭先生云空堦鹤恋丹青影秋雨苔封白石牀题闲居云鸟啼碧树闲临水花满青山静掩门等句皆区区所当避舍者也有集一卷今传\n曹唐字尧宾桂州人初为道士工文赋诗大中间举进士咸通中为使府从事唐与罗隐同时才情不异唐始起清流志趣澹然有淩云之骨追慕古仙子高情往往奇遇而已才思不减前人遂作大游仙诗五十篇又小游仙诗等记其悲欢离合之要大播於时唐尝会隐各论近作隐曰闻兄游仙之制甚佳但中一聨云洞里有天春寂寂人间无路月茫茫乃是鬼耳唐笑曰足下牡丹诗一聨乃咏女子阵若教解语应倾国任是无情也动人於是座客大笑唐平生志甚激昂至是薄宦颇自郁悒为病马诗以自况警聨如尾盘夜雨红丝脆头捽秋风白练低又云风吹病骨无骄气土蚀騘花见卧痕又云饮惊白露泉花冷吃怕清秋豆叶寒皆脍炙人口忽一日昼梦仙女鸾佩花冠衣如烟雾倚树吟咏唐天台刘阮诗若欲相招而出者唐惊觉颇怪之明日暴病卒亦感忆之所致也有诗集二卷今传於世\n论曰人云有徳者或无文有文者或无徳文徳兼备古今所难典论谓文人相轻从古而然各以所长相轻所短矛楯之极则是非锋起隙始於毫末祸大於丘山前後类此多矣夫以口舌常谈无益无损每至丧清徳负良友承轻薄子之名乏藏疾匿瑕之量如此功业未见其超者矣君子所愼也\n郑巢钱塘人大中间举进士时姚合号诗宗为杭州刺史巢献所业日游门馆累陪登览燕集大得奬重如门生礼效合体格服膺无斁句意清新巢性疎野两浙湖山寺宇幽胜多名僧外学高妙相与往还酬酢竟亦不仕而终有诗一卷今行於世\n于武陵大中时举进士不称意携书与琴往来商洛巴蜀间或隐於卜中存独醒之意避地嘿嘿语不及荣贵少与时辈交游尝南来至潇湘爱汀洲芳草况是古骚人旧国风景不殊欲卜居未果归老嵩阳\n高骈〈按新唐书骈字千里〉为西川节度筑成都城四十里朝廷疑之以宴间咏风筝诗云依稀似曲才堪听又被风吹别调中明日诏下移鎭渚宫亦䜟之类也骈封渤海郡王弃人间事絶女色属意神仙鄱阳商侩吕用之妄言能以妖术役鬼神及狂人诸葛殷张守一之徒凡十余辈相引而进多为谬悠长年飞化之说羽衣鹤氅诡辩风生骈事之若神焉骈手握王爵口含天宪国家倚之名书於唐史叛臣传亦何足道矣有诗一卷今传大顺中谢蟠隐为之序〈按骈传全文已佚今就永乐大典所载五条编录〉\n李昌符字岩梦咸通四年礼部侍郎萧仿下进士工诗在长安与郑谷酬赠仕终膳部员外郎尝作奴婢诗五十首有云不论秋菊与春花个个能噇空肚茶无事莫教频入库每般闲物要些些等句後为御史劾奏以为轻薄为文多妨政务亏严重之徳唱俳戏之风谪去匏系终身有集一卷行於世\n汪遵宣州泾县人幼为小吏昼夜读书良苦人皆不觉咸通七年韩衮榜进士遵初与乡人许棠友善工为絶句诗而深自晦密以家贫难得书必借於人彻夜强记棠实不知一旦辞役就贡棠时先在京师偶送客至灞滻间忽遇遵於途行李索然棠讯之曰汪都何事来都者吏之呼也遵曰此来就贡棠怒曰小吏不忖而欲与棠同研席乎甚侮慢之後遵成名五年棠始及第洛中有李相徳裕平泉庄佳景殊胜李未几坐事贬朱崖遵过题诗云平泉风景好高眠水色岚光满目前刚欲平他不平事至今惆怅满南边又过杨相宅诗云倚伏从来事不遥无何平地起青霄才到青霄却平地门对古槐空寂寥俱为时人称赏其余警策称是有集今传论曰汪遵泾之一走耳拔身卑汚夺誉文苑家贫借书以夜继日古人阅市偷光殆不过此昔沟中之断今席上之珍丈夫自修当如是耶与夫朱门富家积书万卷束在高阁尘暗籖轴蠧落帙帷网好学之名欺盲聋之俗非三变之败无一展之期谚曰金玉有余卖鎭宅书呜呼哀哉\n翁绶咸通六年中书舍人李蔚下进士工诗多近体变古乐府音韵虽响风骨憔悴眞晚唐之移习也後亦间关名不甚显固知闾巷之人欲砥行立名者非附青云之士恶能施於後世哉有诗今传\n沈光吴兴人咸通七年礼部侍郎赵骘下进士工文章古诗标致翘楚大得美称尝作洞庭张乐赋韦岫见之曰此乃一片宫商也又如太白酒楼记等文皆仪表於世有诗集及云梦子五卷并传光风鉴澄爽神情俊迈後仕终御史云\n邵谒韶州翁源县人少为县㕔吏客至仓卒令怒其不榰床迎待逐去遂截髻着县门上发愤读书书堂距县十余里隐起水心谒平居如里中儿未冠者髪鬅鬙野服苦吟工古调咸通七年抵京师𨽻国子监时温庭筠主试悯擢寒苦乃榜谒诗三十余篇以振公道曰前件进士识略精微堪裨教化声词激切曲备风謡标题命篇时所难及灯烛之下雄辞卓然诚宜榜示衆人不敢独专华藻仍请申堂并榜礼部已而释褐後赴官不知所终他日县民祠神者持帻舞铃忽自称邵先辈降乡里前辈皆至作礼问曰今者辱来能强为我赋诗乎巫即书一絶云青山山下少年郎失意当时别故乡惆怅不堪回首望隔溪遥见旧书堂词咏凄苦虽椽笔不逮乡老中晓声病者至为感泣咨嗟今有诗一巻传於世司空图字表圣河中人父舆大中时为商州刺史图咸通十年归仁绍榜进士主司王凝初典绦州图时方应举自别墅到郡上谒去阍吏遽申司空秀才出郭门外入郭访亲知即不造郡斋公谓其尊敬愈重之及知贡举图第四人捷同年鄙薄者谤曰此司空图得一名也公颇闻因宴全榜宣言曰凝叨忝文柄今年榜帖专为司空先辈一人而已由是名益振未几凝为宣歙观察使辟置幕府召拜殿中侍御史不忍去凝府台劾左迁光禄寺主簿卢相携还朝过陕虢访图深爱重留诗曰氏族司空贵官班御史雄老夫如且在未可叹途穷景福中拜谏议大夫不赴昭宗在华州召为兵部侍郎以足疾自乞听还图家本中条山王官谷有先人田庐遂隐不出作亭观素室悉图唐兴节士文人像尝曰某宦情萧索百事无能量才一宜休揣分二宜休耄而瞶三宜休遂名其亭曰三休作文以申志自号知非子耐辱居士言涉诡激不常欲免当时之祸初以风雨夜得古寳劒惨淡精灵常佩出入性苦吟举笔缘兴几千万篇自致於绳检之外豫置冢棺遇胜日引客坐圹中赋诗酌酒沾醉高歌客有难者曰君何不广耶生死一致吾宁暂游此中哉岁时祠祷与闾里父老鼓舞相乐时寇盗所过虀粉独不入谷中知图贤如古王蠋也士民依以避难後闻哀帝遇弑不食扼腕呕血数升而卒年七十有二有一鸣集三十卷行於世\n崔道融荆人也自号东瓯散人与司空图为诗友出为永嘉宰工絶句语意妙甚如铜雀妓云歌咽新翻曲香销旧赐衣陵园风雨暗不见六龙归春闺云寒食月明雨落花香满泥佳人持锦字无雁寄辽西寄人云淡淡长江水悠悠逺客情落花相与恨到地一无声寒食夜云满地梨花白风吹碎月明大家寒食夜独贮逺乡情等尚衆谁谓晚唐间忽有此作使古人复生亦不多让可谓出乎其类拔乎其萃者矣人悉推服其风情雅度犹恨出处未能梗槩之也有申唐集十卷自序云乾符乙卯夏寓永嘉山斋收拾草稿得五百余篇今存於世聂夷中字坦之河南人也咸通十二年礼部侍郎高湜下进士与许棠公乘亿同袍时兵革多务不暇铨注夷中滞长安久皂裘已敝黄粮如珠始得调华隂县尉之官惟琴书而已性俭久沈草泽备尝辛楚率多伤俗闵时之作哀稼穑之艰难适值险阻进退维谷才足而命屯有志卒爽含蓄讽刺亦有谓焉古乐府尤得体皆警省之辞裨补政治乐而不淫哀而不伤正国风之义也其诗一卷今传\n许棠字文化宣州泾人也於诗文性僻少合既久困名场时马戴佐大同军幕为词宗棠往谒之一见如旧交留连累月但从事诗酒而已未尝问所欲一旦大会宾客命使以棠家书授之棠惊愕不喻其来啓缄即知戴潜遣一介恤其家矣古人温良泛爱振穷周急谦退不伐亦皆絶异之资也咸通十二年李筠榜进士及第时及知命尝曰自得一第稍觉筋骨轻健愈於少年则知一名乃孤进之还丹也调泾县尉之官郑谷送诗曰白头新作尉县在故山中高第能卑宦前贤尚此风後潦倒辞荣初作洞庭诗脍炙时口号许洞庭云今集一卷传世\n周繇〈按唐诗纪事繇字为宪〉江南人咸通十三年郑昌图榜进士调福昌县尉家贫生理索寞只苦嗜篇韵俯有思仰有咏深造阃域时号为诗禅警聨如送人尉黔中云公庭飞白鸟官俸请丹砂望海云岛间应有国波外恐无天甘露寺云殿锁南朝像龛传外国僧又山从平地有水到逺天无又白云连菌阁碧树尽芜城江州上薛能尚书云树翳楼台月帆飞鼓角风又郡斋多岳客乡户半渔翁等句甚多读之皆使人竦诚好手也落拓盃酒无荣辱之累所交游悉一时名公集今传世同登第有张演者工诗间见一二篇亦佳作也\n论曰尝谓禅家者流论有大小乗有邪正法要能具正法眼方为第一义出有无间若声闻辟支四果已非正也况又堕野狐外道鬼窟中乎言诗亦然宗派或殊风义必合品则有神妙体则有古今才则有圣凡时则有取舍自晋魏以降递至盛唐大歴元和以下逮晚年考其时变商其格制其邪正了然在目不能隐也经云过而不改是谓过矣悟门洞开慧烛深照顿渐之境各天所赋观於时以诗禅许周繇为其不入邪见直臻上乗固知其衣冠於裸人之国矣昔人谓学诗如学仙此之类欤\n皮日休〈按唐诗纪事日休字袭美襄阳人〉隐居鹿门山性嗜酒癖诗号醉吟先生又号间气布衣言己天地之间气也以文章自负尤喜箴铭咸通八年礼部侍郎郑愚下及第为着作郎迁太常博士时值末年虎狼放纵百姓手足无所措上下所行皆大乱之道遂作鹿门隐诗六十篇多讥切谬政有云毁人者自毁之誉人者自誉之又曰不思而立言不知而定交吾其惮也在乡里与陆龟䝉交若金兰日相赠和性冲泊无营临难不惧乾符丧乱东出关陷巢贼中巢惜其才授以翰林学士日休惶恐局踧欲死未能刼令作䜟文以惑衆曰欲知圣人姓田八二十一欲知圣人名果头三屈律贼疑其衷恨必讥己遂杀之临刑神色自若知与不知皆痛惋也日休自集所为文十卷名文薮及诗集一卷滑台集七卷又着皮氏鹿门家钞九十卷并传\n郑谷〈按新唐书艺文志注谷字守愚袁州人而唐诗纪事则云谷字若愚〉谷父史开成中为永州刺史谷幼颖悟絶伦七岁能咏司空侍郎图与史同院见而竒之问曰予诗有病否曰大夫曲江晚望云村南斜日闲回首一对鸳鸯浴渡头此意深矣司空拊谷背曰当为一代风骚主也光啓三年右丞栁玭下第进士授京兆鄠县尉迁右拾遗补阙乾宁四年为都官郎中诗家称郑都官又尝赋鹧鸪警絶复称郑鹧鸪云未几告归退隐仰山书堂卒於北岩别墅谷诗清婉明白不俚而切为薛能李频所赏与许棠任涛张蠙李栖逺张乔喻坦之周繇温宪李昌符唱答往还号芳林十哲谷多结契山僧曰蜀茶似僧未必皆美不能舍之齐已携诗卷来袁谒谷早梅云前村深雪里昨夜数枝开谷曰数枝非早也未若一枝佳已不觉设拜曰我一字师也尝从僖宗登三峰朝谒之暇寓於云台道舍编所作为云台编三卷归编宜阳集三卷及撰国风正诀一卷分六门摭诗聨注其比象君臣贤否国家治乱之意今并传焉\n张乔池州人也隐居九华山有高致十年不窥园以苦学诗句清雅迥少其伦当时东南多才子如许棠喻坦之剧燕吴宰任涛周繇张蠙郑谷李栖逺李昌符与乔亦称十哲俱以韵律驰声大顺中京兆府解试李参军频时主文试以月中桂诗乔云根非生下土叶不坠秋风遂擅其年频以许棠久困屋以为首荐乔与喻坦之复受放薛尚书知之欲表於朝以他不果竟岨峿名途徒得一进耳有诗集二卷传世\n胡曾长沙人也咸通中进士初再三下第有诗云翰苑几时休嫁女文昌早晚罢生儿上林新桂年年发不许时人折一枝曾天分高爽意度不凡视人间富贵亦悠悠游歴四方马迹穷岁月所在必公卿馆榖上交不谄下交不渎竒士也尝为汉南节度从事作咏史诗皆题古君臣争战兴废尘迹经览形胜关山亭障江海深阻一一可赏人事虽非风景犹昨每感辄赋俱能使人奋飞至今庸夫孺子亦知传诵後有拟效者不逮矣至於近体律絶等哀怨清楚曲尽幽情擢居中品不过也惜其才茂而身未颖脱痛哉今咏史诗一卷有咸通中人陈盖注及安定集十卷行世\n来鹏豫章人家徐孺子亭边林园自乐师韩栁为文大中咸通间才名藉甚凡十上不得第鹏工诗蓄锐既久自伤年长家贫不达颇亦忿忿故多寓意讥讪当路虽赏清丽不免忤情每为所忌如金钱花云青帝若教花里用牡丹应是得钱人韦岫尚书独赏其才延待幕中携以游蜀又欲纳为壻不果是年力荐夏课献诗有云一夜绿荷风翦破嫌他秋雨不成珠岫以为不祥果失志时遭乱避地客死於维逆旅主人贤而葬之李山甫咸通中累举进士不第落魄有不羁才须髯如㦸能为青白眼生平憎俗子尚豪侠虽箪食豆羮自甘不厌为诗托讽不得志每狂歌痛饮援劒斫地少摅郁郁之气耳後流寓河朔间依乐彦桢为魏博从事不得衆情以陵傲之故无所遇尝有老将诗曰校猎燕山经几春雕弓白羽不离身年来马上浑无力望见飞鸿指似人此伤其蹇薄无成时人怜之後不知所终山甫诗文激切耿耿有齐气多感时懐古之作今集一卷赋二卷并传\n赵光逺丞相隐之犹子也幼而聪悟咸通乾符中称气焰善为诗温庭筠李商隐辈梯媒之恃才不拘小节皆金鞍骏马尝将子弟恣游狭斜着北里志颇述青楼红粉之事及有诗等传於世\n论曰光逺等千金之子厌饫膏粱仰䕃承荣视若谈笑骄侈不期而至矣况年少多材京邑繁盛耳目所荡素少闲邪之虑者哉故辞意多裙裾妖艳之态无足怪矣有孙啓崔珏同时恣心狂狎善为唱和颇陷轻薄无退让之风惟卢弼气象稍严不迁狐惑如边庭四时怨等作赏音大播信不偶然区区凉德徒曰贵介不暇录尚多云\n赵牧不知何许人大中咸通中累举进士不第有俊材负竒节遂舍场屋放浪人间效李长吉为歌诗颇涉狂怪耸动当时蹙金结绣而无痕迹装染其余轻巧之词甚多同时有刘光逺亦慕长吉凡作体效尤能埋没意绪竟不知所终俱有诗传世\n牛峤字延峰陇西人宰相僧孺之後博学有文以歌诗着名乾符五年孙偓榜第四人进士仕歴拾遗补阙尚书郎王建鎭四川辟为判官及伪蜀开国拜给事中有集本三十卷自序云窃慕李长吉所为歌诗辄效之今传於世\n\n唐才子传巻六\n<史部,传记类,总录之属,唐才"},{"title":"巻七","text":"钦定四库全书\n唐才子传巻七 元 辛文房 撰\n高 蟾 任 涛\n罗 隠 罗 邺\n罗 虬 唐彦谦\n崔 鲁 秦韬玉\n李 洞 崔 涂\n郑良士 唐 备〈于濆〉\n呉 融 韩 渥\n王 驾 戴司顔\n王 焕 张 鼎\n卢延让 曹 松\n裴 説 韦 荘\n张 蠙 王贞白\n王 毂 殷文圭\n褚 载 翁承赞\n李 中 李建勲\n孙 鲂 沈 彬〈子廷瑞〉\n江 为 廖 图〈刘昭禹等郑凖〉\n熊 皦 孟宾于\n孟 贯\n高蟾河朔间人乾符三年孔缄榜及第与郑郎中谷为友酬赠称高先辈初累举不上题省墙间曰氷柱数条榰白日天门几扇锁明时阳春发处无根蔕慿仗东风次第吹怨而切是年人论不公又下第上马侍郎云天上碧桃和露种日边红杏倚云栽芙蓉生在秋江上莫向春风怨未开意亦凄楚马怜之又有顔色如花命如叶之句自况时运蹇窒马因力荐明年李昭知贡举遂擢桂官至御史中丞蟾本寒士皇皇於一名十年始就性倜傥离羣稍尚气节人与千金无故即身死亦不受其胸次磊块诗酒能为消破耳诗体则气势雄伟态度谐逺如狂风猛雨之来物物竦动深造理窟亦一竒逢掖也诗集一巻今𫝊\n任涛筠川人也章句之名早擅乾符中应数举毎败於埀成李常侍隲亷察江西素闻涛名取其诗览之有云露漙沙鹤起人卧钓船流大加赏叹曰任涛竒才也何故不成名㑹当荐之特与放乡里杂役仍令本贯优礼时盲俗互有论列隲判曰江西境内凡为诗得及涛者即与放役岂止一任涛而已哉未几涛逝去有才无命大可怜也诗集今𫝊\n罗隠字昭谏钱塘人也少英敏善属文诗笔尤俊㧞养浩然之气乾符初举进士累不第广明中遇乱归乡里时钱尚父镇东南节钺崇重隠欲依焉进谒投素作巻其首章过夏口云一个祢衡容不得思量黄祖漫英雄鏐得之大喜以书辟之曰仲宣逺托刘荆州盖因乱世夫子乐为鲁司冦祗为故乡隠曰是不可去矣遂为掌书记性简傲阔谈高论满座风生好谐谑感遇輙发鏐爱其才前後赐予无数陪从不顷刻相背表迁节度判官盐铁发运使未几奏授着作郎鏐初授镇命沈崧草表谢盛言浙西富庶隠曰今浙西焚荡之余朝臣方切贿赂表奏将鹰犬我矣鏐请隠更之有云天寒而麋鹿曽游日暮而牛羊不下又为贺昭宗改名表云左则姬昌之半字右为虞舜之全文作者称赏转司勲郎中自号江东生魏博节度罗绍威慕其名推宗人之分拜为叔父时亦老矣尝表荐之隠恃才忽睨衆颇憎忌自以当得大用而一第落落𫝊食诸侯因人成事深怨唐室诗文多以讥刺为主虽荒祠木偶莫能免者且介僻寡合不喜军旅献酬俎豆间绰绰有余也隠初贫来赴举过锺陵见营妓云英有才思後一纪下第过之英曰罗秀才尚未脱白隠赠诗云锺陵醉别十余春重见云英掌上身我未成名英未嫁可能俱是不如人与顾云同谒淮南高骈骈不礼骈後为毕将军所杀隠有延和阁之讥又以诗投相国郑畋畋有女姝丽喜诗咏读隠作至张华漫出如丹语不及刘侯一纸书由是切慕之精爽飞越莫知所从隠忽来谒女从帘後窥见迂寝之状不复念矣隠精法书喜笔工苌鳯谓曰笔文章货也今助子取高价即以鴈头笺百幅为赠士大夫踵门问价一致千金率多借重如此所着䜛书䜛本淮海寓言湘南应用集甲乙集外集启事等并行于世\n论曰易戒毋以小善为无益而弗为小恶为无伤而弗去也罗隠以褊急性成动必嘲讪率成漫作顷刻相𫝊以其事业非不五鼎也学术非不经史也夫何齐东野人猥巷小子语及讥诮必以隠为称首凋䘮淳才揄秽徳白日能蔽于浮翳美玉曽玷于青蝇虽亦未必尽然是皆阙慎微之义阮嗣宗臧否不挂口欲免其身如滑稽抗世东方朔之流又不相类也\n罗邺余杭人也家赀钜万父则为盐铁吏子二人俱以文学干进邺尤长律诗时宗人隠虬俱以声格着称遂齐名号三罗隠雄丽而坦率邺清致而聫绵虬则区区而巳咸通中数下第有诗云故乡依旧空归去帝里如同不到来崔安潜侍郎亷问江西邺适飘蓬湘浦间崔素赏其作志在弓旌竟为幕吏所沮既而俯就督邮不得志踉跄北征赴职单于牙帐邺去家愈逺万里沙漠满目谁亲因兹触绪䦨珊无成於邑而卒\n论曰邺素有英资笔端超絶其气宇亦不在诸人下初无箕裘之训顿改门风崛兴音韵驰誉当时非易事也而䟦前疐後絶域无聊独奈其命薄何孔子曰才难信然有诗集一巻今𫝊\n罗虬词藻富赡与族人隠邺齐名咸通间称三罗气宇终不逮广明庚子乱後去从鄜州李孝恭为从事虬狂荡无检束时雕隂籍中有妓杜红儿善歌舞姿色殊絶尝为副戎属意㑹副戎聘隣道虬乆慕之至是请红儿歌赠以缯彩孝恭以为副戎所盼为从事歌则非礼勿令受贶虬不称意怒拂衣起诘旦手刃杀之孝恭以虬激已坐之顷㑹赦虬追其寃于是取古之美女有姿艳才徳者作絶句一百首以比红儿当时盛𫝊此外不见有他作体固凡庸无大可采序曰红儿美貎年少机智慧悟不与羣妓等余知红者择古灼然美色优劣于章句间其卒章云花落尘中玉堕泥香魂应上窈娘堤欲知此恨无穷处长倩城乌夜夜啼情极哀切初以白刃相加今曰余知红者虬实一狂夫也且声律之道大爽姑录为笑谈耳\n唐彦谦〈按新旧唐书彦谦字茂业〉才高负气毫髪逆意大怒叵禁博学足艺尤长於诗道古心雄发言不苟极能用事如自已出初师温庭筠风调逼似故多纎丽之词後变淳雅尊崇工部唐人效甫者惟彦谦一人而已〈按此𫝊有阙文〉崔鲁广明间举进士工为杂文才丽而荡诗慕杜紫微风范警句絶多如梅花云强半瘦因前夜雪数枝愁向晚来天又初开已入雕梁画未落先愁玉笛吹莲花云何人觧把无尘袖盛取清香尽日怜山鹊云一畨春雨吹巢冷半朶山花咽觜香又别题云云生柱础降龙地露洗林峦放鹤天等皆绮制精深脍炙人口颇嗜酒无徳尝醉辱陆肱郎中旦日惭甚为诗谢曰醉时颠蹶醒时羞麴蘖催人不自由叵耐一双穷相眼不堪花卉在前头陆亦谅之悠悠乱世竟无所成鲁诗善於状景咏物读之如咽氷雪心爽神怡能逺声病气象清楚格调且高中间别有一种风情佳作也诗三百余篇名无机集今𫝊\n秦韬玉〈按新唐书艺文志注云韬玉字中明唐诗纪事云京兆人书録觧题云韬玉田令孜客僖宗中和二年特赐及第〉赋湘江诗云女娲罗裙长百尺搭在湘江作山色又云岚光楚岫和空碧秋染湘江到底清由是知名号为絶唱〈按此𫝊有阙文〉\n李洞字才江雍州人诸王之孙也家贫吟极苦至废寝食酷慕贾长江遂铜写岛像戴之巾中常持数珠念贾岛佛一日千遍人有喜岛诗者洞必手録岛诗赠之丁寜再四曰此无异佛经归焚香拜之其仰慕一何如是之切也然洞诗逼真似岛新竒或过之时人多诮其僻澁不贵其卓峭唯呉融赏异融以大才八靣受敌新律着称游刃颇攻骚雅尝以百篇示洞洞曰大兄所示中一聫暖漾鱼遗子晴游鹿引麛絶妙也融不怨所鄙而善其所许洞诗大畧如终南山云残阳高照蜀败叶逺浮泾斸竹烟岚冻偷湫雨雹腥逺平丹鳯阙冷射五侯㕔赠司空图云马饥飡落叶鹤病晒残阳又曰巻箔清溪月敲松紫阁书送僧云越讲迎骑象蕃斋懴射雕送僧游南海云岛屿分诸国星河共一天夜云药杵声中捣残梦茶铛影里煑孤灯皆伟㧞时流者昭宗时凡三上不第裴公第二榜帘前献诗云公道此时如不得昭陵恸哭一生休果失意流落往来寓蜀而卒初岛任长江乃东蜀塜在其处郑谷哭洞诗云得近长江死想君胜在生言死生不相逺也洞尝集岛警句五十聫及唐诸人警句五十聨为诗句图自为之序及所为诗一巻并𫝊\n崔涂字礼山光启四年郑贻矩榜进士及第工诗深造理窟端能竦动人意冩景状懐往往宣陶肺腑亦穷年羇旅壮嵗上巴蜀老大游陇山家寄江南毎多离怨之作警策如流年川暗度往事月空明巫娥云江山非旧主云雨是前身又如病知新事少老别故交难孤鴈云渚云低暗度闗月冷相随山寺云夕阳高鸟过踈雨一钟残又谷树云埋老僧牕瀑照寒鹦鹉洲云曹瞒尚不能容物黄祖何因觧爱才春夕云胡蝶梦中家万里杜鹃枝上月三更陇上云三声戍角边城暮万里乡心塞草春过峡云五千里外三年客十二峰前一望秋等聫作者於此敛袵意味俱逺大名不虚有诗一巻今行於世\n郑良士字君梦咸通中累举进士不第昭宗时自表献诗五百余篇敕授补阙而终以布衣一旦俯拾青紫易若反掌浮俗莫不骇羡难其比也今有白岩集十巻𫝊世\n论曰旧言诗或穷人或逹人逹者良士是矣亦命之所为诗何能与过诗则不揣其本也\n唐备龙纪元年进士工古诗多涵讽刺颇干教化非浮艳轻斐之作与同时于濆者〈按新唐书艺文志注濆字子漪书録觧题濆咸通二年进士〉共一机轴大为时流所许备诗有天若无雪霜青松不如草地若无山川何人重平道又狂风㧞倒树树倒根已露上有数枝藤青青犹未悟又一日天无风四溟波自息人心风不吹波浪高百尺又别家云兄弟惜分离拣日皆言恶予读对花云花开蝶满枝花谢蝶来稀惟有旧巢燕主人贫亦归等诗发语浇俗至今人话间必举以为警戒足见之矣余诗多𫝊\n吴融〈按新唐书云融字子华越州山隂人龙纪初及进士第〉天复元年元旦东内反正既御楼融最先至上命於前座草数十诏简备精当曽不顷刻皆中㫖大加激赏进户部侍郎〈按融𫝊祗存此数语余并阙〉\n韩偓京兆人〈按新唐书偓字致光京兆万年人〉龙纪元年礼部侍郎赵宗榜擢第天复中王溥荐为翰林学士迁中书舍人从昭宗幸鳯翔进兵部侍郎翰林承㫖尝与崔𦙍定䇿诛刘季述昭宗反正论为功臣帝励精政事偓处可机宻率与上意合欲相者三四让不敢当偓喜侵侮有位朱全忠亦恶之乃构祸贬濮州司马帝流涕曰我左右无人矣天佑二年复召为学士偓不敢入朝挈其族南依王审知而卒偓自号玉山樵人工诗有集一巻词多侧艳新巧又作金銮宻记五卷今并𫝊\n王驾字大用蒲中人自号守素先生大顺元年杨赞禹榜登第授校书郎仕至礼部员外郎弃官嘉遁於别业与郑谷司空图为诗友才名籍甚图尝与驾书评诗曰国初雅风特盛沈宋始兴之後杰出於江宁宏思於李杜极矣右丞苏州趣味澄夐若清流之贯逺大歴十数公抑又其次元白力勍而气孱乃都市豪估耳刘梦得杨巨源亦各有胜㑹浪仙无可刘得仁辈时得佳致亦足涤烦厥後所闻徒褊浅矣河汾蟠欝之气宜继起有人今王生寓居其间沉渍益乆五言所得长於思与境偕乃诗家之所尚者则前所谓必推於其类岂止神跃色扬而已哉驾得书自谓誉已不虚矣当时价重乃如此也今集六巻行於世\n戴司顔大顺元年杨赞禹榜进士及第与王驾同袍有诗名气宇盘礴毎有过人遂得名家岂泛然矣有集今𫝊\n王焕〈按唐诗纪事焕字羣吉〉大顺二年礼部侍郎裴贽下进士及第俄自左史拜考功员外郎同年皆美除焕首倡感恩长句上谢座主裴公当时甚荣之後以礼部侍郎致仕年九十见睢阳五老图焕工诗情极婉丽尝为惆怅诗十三首悉古佳人才子深懐感怨者以崔氏莺莺汉武李夫人陈乐昌主緑珠张丽华王明君及苏武刘阮辈事成篇哀伤媚妩如谢家池馆花笼月萧寺房廊竹颭风夜半酒醒慿槛立所思多在别离中又梦𥚃分明入汉宫觉来灯背锦屏空紫台月落闗山晓肠断君王信画工等皆絶唱喧炙士林在晚唐诸人中霄壤不侔矣有集今𫝊\n张鼎字台业闽中人景福二年崔胶榜进士工诗离羣㧞类集一巻及着唐诗主客图等并𫝊於世\n卢延让字子善范阳人也有卓絶之才光化三年裴格榜进士朗陵雷满荐辟之满败归伪蜀授水部员外郎累迁给事中卒官刑部侍郎延让师许下薛尚书为诗词意入僻不竞纎巧且多健语下士大笑之初呉融为侍御史出官峡中时延让布衣薄游荆渚贫无巻轴未遑贽谒㑹融弟得延让诗百余篇融覧其警聫如宿东林云两三条电欲为雨七八个星犹在天旅舍言懐云名纸毛生五门下家童骨立六街中赠元上人云高僧觧语牙无水老鹤能飞骨有风蜀道云云间閙铎骡䭾去雪里残骸虎拽来又云树上诹谘批颊鸟窻间逼駮扣头虫等句大惊曰此去人逺絶自无蹈袭非寻常耳此子後必垂名余昔在翰林召对上曽举其臂鹰健卒横氊帽骑马佳人巻画衫一聨虽浅近然自成一体名家今则信然矣〈按此条全本杨大年谈苑考谈苑原文云卢延逊诗浅近人皆笑之惟呉融独重之且云後必垂名延逊诗亦有佳处如宿东林云云余在翰林尝召对上举延逊臂鹰骑马二句虽浅近亦自成一体也考宋避濮安懿王名故讳让字延逊即延让也但翰林召对数语乃大年自述其知制诰时事原文以为呉融之言舛谬殊甚谨订於此〉遂厚礼遇赠给甚多融雪中寄诗云永日应无食终宵必有诗後夺科第多融之力也今诗一巻𫝊世\n曹松字梦徴舒州人也学贾岛为诗深入幽境然无枯淡之癖尤长启事不减山公早嵗未逹常避乱来栖洪都西山初在建州依李频频卒後往来一无所遇光化四年礼部侍郎杜徳祥下与王希羽刘象柯崇郑希顔同登第年皆七十余矣号为五老榜时值新平内难朝廷以放进士为喜特授校书郎而卒松野性方直罕接俗事故拙於进宦逍遥林泽寓情虚无苦极於诗然别有一种风味不沦乎怪也文集三巻今𫝊\n裴说工诗足竒思非意表琢炼不举笔有岛洞之风大得盛名初年窘迫乱离奔走道路有诗云避乱一身多见者悲之有集今𫝊\n韦荘〈按书录觧题荘乾宁元年进士〉少孤贫力学才敏过人荘应举时正黄巢犯阙兵火交作遂着秦妇吟有云内库烧为锦綉灰天街踏尽却重回乱定公卿多讶之号为秦妇吟秀才荘自来成都寻得杜少陵所居浣花溪故址虽芜没已乆而柱砥犹存遂诛茅重作草堂而居焉性俭约称薪而爨数米而炊逹人鄙之早尝冦乱间闗顿踬携家来越中弟妹散居诸郡西江湖南所在薄游举目有山河之异故於流离漂泛寓目缘情子期懐旧之辞王粲伤时之制或离羣轸虑或反袂兴悲四愁九怨之文一咏一觞之作俱能感动人也〈按此𫝊有阙文〉\n张蠙〈按新唐书艺文志注蠙字象文〉家贫累下第留滞长安赋诗云月里路从何处上江边身合几时归十年九陌寒风夜梦扫芦花絮客衣及第释褐後为金堂令〈按书录觧题蠙乾宁二年进士〉王衍与徐后游大慈寺见壁间题墙头细雨垂纎草水靣囘风聚落花爱赏乆之问谁作左右以蠙对因给牋令以诗进蠙上二百篇衍尤重待赐白金千两\n王贞白字有道信州永丰人也乾宁二年登第後物议纷纷诏翰林学士陆扆於内殿覆试中选授校书郎时登第後七年矣郑谷以诗赠曰殿前新进士阙下校书郎初兰溪僧贯休雅得名与贞白所居相去不逺而未㑹尝寄御沟诗有云此波涵帝泽无处濯尘缨後㑹语及此休曰剩一字贞白拂袂而去休曰此公思敏当即来休书字於掌心逡巡贞白还曰此中涵帝泽如何休以掌示之无异所改遂订深契後值天王狩于岐廼退居着书不复干禄当时大获芳誉性恬和明易象手编所为诗三百篇及赋文等为灵溪集七巻𫝊於世卒𦵏家山贞白学力精赡笃志於诗清润典雅呼吸间两获科甲自致於青云之上文价可知矣深惟存亡取舍之义进而就禄退而保身君子也梁陶𢎞景弃官隠居三茅国事必谘请称山中宰相号贞白今王公盖慕其为人而云尔\n王毂字虚中宜春人自号临沂子以歌诗擅名长於乐府未第时尝为玉树曲云璧月夜琼树春莺舌泠泠词调新当时狎客尽持禄直谏犯顔无一人歌未阕晋王剑上粘腥血君臣犹在醉乡中一靣已无陈日月大播人口适有同人为无頼辈所殴毂前救之曰莫无礼我便是道君臣犹在醉乡中者无頼闻之惭谢而退毂亦大节士轻财重义为乡里所誉颇不平乆困适生离难间辞多寄寓比兴之作无不知名乾宁五年羊绍素榜进士歴国子博士後以郎官致仕有诗三巻于时宦逹俱素餐尸位卖降恐後之徒毂因撰前代忠臣临老不变者为图一巻及观光集一巻并𫝊\n殷文圭字表儒池州青阳人也乾宁五年礼部侍郎裴贽下进士初未第时道中尝逢一老叟目文圭乆之谓人曰向者布衣緑眉方口神仙中人也如学道可以冲虚不尔垂大名於天下未几兵马振动大驾幸三峯文圭以梁王表荐及第时杨令公行宻镇淮奄有宣浙汴之间榛梗既乆文圭辞亲间道至行在无何随榜为吏部侍郎裴枢宣慰判官记室参军至大梁以身事叩梁王王又上表荐之文圭後餙非遍投启事公卿间曰於菟猎食非求尺璧之珍爰居避风不望洪钟之乐俄为多言者所发後更道由宋汴亟驰过梁王大怒亟遣追捕已不及矣为诗有登龙集㝠搜集笔耕词氷镂录从军藳等集𫝊世\n论曰唐季文体浇漓才调荒秽稍稍作者强名曰诗南郭之竽苟存於衆响非复盛时之万一也如王周刘兼司马札苏拯许琳李咸用等数人虽有集相𫝊皆气卑格下负鱼目唐突之惭窃碔砆韫袭之滥所谓家有敝帚享之千金不自见之患也文圭稍入风度间见竒崛其殆庶几乎\n褚载字厚之家贫客梁宋间困甚以诗投襄阳节度使邢君牙云西风昨夜坠红兰一宿邮亭事万般无地可耕归不得有恩堪报死何难流年怕老看将老百计求安未得安一卷新诗满懐泪频来门馆诉饥寒君牙怜之赠绢十匹荐於郑滑节度使不行乾宁五年礼部侍郎裴贽知贡举君牙又荐之遂擢第初文徳中刘子长出镇浙西行次江西时陆威侍郎犹为郎吏亦寓于此载缄二轴投谒误以子长之巻靣贽於威威览之连见数字触家讳威矍然载错愕曰似大误寻谢以长牋略曰曹兴之图画虽精终慙误笔殷浩之兢持太过翻逹空函威激赏而终不能引㧞後竟流落而卒集三巻今𫝊於世\n翁承赞〈按新唐书艺文志注云承赞字文尧乾宁进士唐诗纪事云闽人〉工诗体貎甚伟且诙谐名动公侯唐人应试毎在八月谚曰槐花黄举子忙承赞咏槐花云雨中粧㸃望中黄勾引蝉声送夕阳忆得当年随计吏马蹄终日为君忙〈按此𫝊有阙文〉李中字有中九江人也唐末尝第进士为新涂淦阳吉水三县令仕终水部郎中孟賔于赏其工吟絶似方干贾岛时复过之如暖风医病草甘雨洗荒村又贫来卖书剑病起忆江湖又闲花半落处幽鸟未来时又千里梦随残月断一声蝉送早秋来又残阳影里水东注芳草烟中人独行又闲寻野寺聴秋水寄睡僧窻到夕阳又香入肌肤花洞酒冷侵魂梦石床云又西园雨过好花尽南陌人稀芳草深等句惊人泣鬼之语也有碧云集今𫝊\n李建勲字致尧广陵人仕南唐为宰相後罢出镇临川未几以司徒致仕赐号锺山公年已八十志尚散逸多从仙侣参究𤣥门时宋齐丘有道气在洪州西山建勲造谒致敬欲授真果题诗赠云春来涨水波如活晓起西山势似行玉洞有人经刼在携竿步步就长生归高安别墅一夕无病而逝能文赋诗琢链颇工调既平妥终少惊人之句也有锺山集二十巻行於世\n孙鲂〈按马令南唐书鲂字伯鱼唐诗纪事鲂南昌人〉唐末处士也与沈彬李建勲同时倡和亦多鲂有夜坐诗为世称玩建勲日与谈讌尝匿鲂於斋幕中待沈彬来乃问曰鲂夜坐诗如何彬曰田舍翁火炉头之语何足道哉鲂从幕中出诮彬曰何讥谤之甚彬曰画多灰渐冷坐乆席成痕此非田舍翁炉上谁有此况一座大笑及金山寺诗云天多剰得月地少不生尘当时谓骚情风韵不减张祜有诗五巻今𫝊\n沈彬字子文瑞州高安人自㓜苦学属末嵗离乱随计不㨗南游湖湘隠云阳山数年归乡里时南唐李昪镇金陵旁罗俊逸名儒宿老必命郡县起之彬赴辟知昪欲取杨氏因献画山水诗云须知手笔安排定不怕山河整顿难昪覧之大喜授秘书郎保大中以尚书郎致仕归徙居宜春初经板荡与韦荘杜光庭贯休俱避难在蜀多见酬酢彬临终指𦵏处示家人及窆果掘得一空塚有漆灯青荧圹头立一铜板篆文曰佳城今已开虽开不𦵏埋漆灯终未灭留待沈彬来遂窀穸於此有诗集一巻𫝊世彬第二子廷瑞性坦率豪於觞咏举动异俗盛夏附火严冬单衣或遇崇山野水古洞幽坛竟日不返时人异之呼为沈道者士大夫多邀至门馆一日邑宰戏问何日道成廷瑞即留诗曰何须问我道成时紫府清都自有期手掘药苖人不识体涵僊骨俗争知宰惊谢後浪游四方或𫝊仙去也\n江为〈按书録觧题为建安人〉举进士輙不第工诗有天形围泽国秋色露人家身寒花露重江晚水烟㣲等句脍炙人口少逰白鹿寺有句云吟登萧寺旃檀阁醉倚王家玳瑁筵後主南迁见之曰此人大是富贵家〈按此𫝊有阙文〉\n廖图字赞禹䖍州䖍化人文学博赡为时辈所服湖南马氏辟致幕下奏授天策府学士与同时刘昭禹李𢎞臯徐仲雅蔡昆韦鼎释虚中俱以文藻知名赓倡迭和齐巳时寓渚宫与图相去千里而毎诗筒往来不絶警䇿极多必见高致集二巻今行於世时有荆南从事郑准亦工诗与僧尚顔多所酬赠诗亦𫝊\n熊皦九华山人唐清泰二年进士刘景岩节度延安辟为从事晋天福中説景岩归朝以功擢右谏议竟坐累黜为上津令工古律诗语意俱妙尝赋早梅云一夜开欲尽百花犹未知甚𫝊赏士林且知其必遇今有屠龙集南金集合五巻𫝊世学士陶榖序之\n孟賔于〈按郡阁雅谈賔于字国仪连州人〉晋天福九年礼部郎符䝉知贡賔于帘下投诗云那堪雨後更闻蝉溪隔重湖路七千忆得故园杨栁岸全家送上渡头船䝉得诗以为相见之晚遂擢第时已败六举矣〈按此传有阙文〉\n孟贯闽中人为性踈野不以荣宦为意喜篇章周世宗幸广陵贯时大有诗价世宗亦闻之因缮录一巻献上首篇书贻谭先生云不伐有巢树多移无主花世宗不恱曰朕伐叛吊民何得有有巢无主之说献朕则可他人则卿必不免不复终巻赐释褐进士虚名而巳不知其终有诗集今𫝊\n论曰孟子曰予之不遇鲁侯天也至唐开元孟浩然流落帝心和璧堕地孟郊之出处梗概苦艰薄宦而死今"},{"title":"巻八","text":"钦定四库全书\n唐才子传巻八 元 辛文房 撰隐逸\n王 绩 卢 鸿\n张 彪 刘方平\n秦 系 张志和\n陆 羽 张衆甫〈赵微明等〉\n朱 放 卢 仝\n方 干 陆龟䝉\n周 朴 唐 求\n仙\n吴 筠 顾 况〈子非熊〉\n刘 商 韩 湘\n施肩吾 陈 陶\n吕 岩 陈 抟\n僧\n灵 一 皎 然\n无 可 清 塞\n虚 中 贯 休\n齐 己\n妓\n薛 涛\n女道士\n李季兰 鱼𤣥机\n王绩〈按新唐书绩字无功〉龙门人王文中子通之弟也年十五游长安谒杨素一座服其英敏目爲神仙童子举孝亷授六合县丞以嗜酒妨政遂托病风轻舟夜遁叹曰网罗在天吾将安之乃还乡里武德中诏以前官待诏门下省弟静谓绩曰待诏可乐否曰待诏俸薄况萧索但良醖三升差可恋耳江国公闻之曰三升良醖未足以绊王先生特判日给一斗时人呼爲斗酒学士贞观初以疾罢归河渚间有仲长子光者亦隐士也无妻子绩爱其真遂相近结庐日与对酌有奴婢数人多种黍春秋酿酒养鳬鴈莳药草自供以周易庄老置床头无他用心也自号东臯子虽刺史谒见皆不答终於家绩髙情胜气独步当时性简傲好饮酒能尽五斗自着五斗先生传弹琴为诗着文撰酒经一巻酒谱一巻诗赋等传世\n卢鸿字颢然隐居嵩山博学善八分书工诗兼画山水树石开元初𤣥宗备礼徴再三不至诏曰鸿有泰一之道中庸之德鈎深诣㣲确乎自髙诏书屡下每輙辞托使朕虚心引领于今有年虽得素履幽人之介而失考父滋恭之谊礼有大伦君臣之义不可废也有司其齎束帛之具重宣兹㫖想有以翻然易节副朕意焉鸿至谒见不拜宰相问状答曰礼者忠信所薄臣敢以忠信见帝召升内殿置酒拜谏议大夫固辞复下诏许还山将行赐隐居服官营草堂鸿到山中广精舍从学者五百人及卒诏赐万钱营葬\n张彪颍上人初赴举无所遇适遭丧乱奉老母避地隐居嵩山供养至谨与孟云卿为中表俱工诗调云卿有赠云善道居贫贱洁服䝉尘埃行行无定心坎𡒄难归来\n刘方平河南人白晳美仪容二十工词隐居颍阳大谷髙尚不仕善画山水时汧国公李勉延致斋中甚敬爱之欲荐于朝不忍屈辞还旧隐工诗有集传世\n秦系〈按新唐书系字公绪〉㑹稽人天宝末避乱剡溪自称东海钓客薛兼训奏为仓曹参军不就客泉州南安九日山中有大杉百余章俗传东晋时所植系结屋其上穴石为研注老子弥年不出姜公辅以直言罢为泉州别驾见系輙穷日不能去筑室与相近遂忘流落之苦公辅卒妻子在逺系为营葬山下其好义如此\n张志和〈按新唐书志和字子同婺州金华人〉擢明经命待诏翰林以亲丧不复仕居江湖性髙迈自称烟波钓徒撰𤣥真子十二巻兄鹤龄恐其遯世为筑室越州东郭茅茨数椽花竹掩映尝豹席椶屫沿溪埀钓每不投饵志不在鱼也志和待诏翰林时帝尝赐奴婢各一人志和配为夫妇号渔童樵青与陆羽尝为顔平原食客平原初来刺湖州志和造谒顔请以舟敝欲为更之曰愿为浮家泛宅徃来苕霅间足矣善画山水酒酣或击鼓吹笛䑛笔輙就曲尽天真自撰渔歌便复画之兴趣髙逺人不能及陆羽字鸿渐不知所生初竟陵禅师智积得婴儿於水濵育为弟子及长耻从削发以易自筮得蹇之渐曰鸿渐于陆其羽可用为仪以为姓名有学愧一事不尽其妙性诙谐少年匿优人中撰笑谈万言天宝间署羽伶师後遁去古人所谓洁其行而秽其迹者上元初结庐苕溪上闭门读书名僧髙士谈讌终日貌寝口吃而辩闻人善若在已与人期虽阻虎狼不避也自称桑苎翁又号东冈子工古调歌诗兴极闲雅着书甚多扁舟徃来山寺唯纱巾藤鞋短褐犊鼻击林木弄流水或行旷野中诵古诗徘徊至月黒兴尽恸哭而返当时以比接舆也与皎然上人为忘年之交有诏拜太子文学羽嗜茶着茶经三巻言茶之原之法之具时号茶仙天下益知饮茶矣鬻茗家以瓷陶羽形祀为神买十茶器得一鸿渐初御史大夫李季卿宣慰江南喜茶知羽召之羽野服挈具而入李曰陆君善茶天下所知扬子中泠水又殊絶今二妙千载一遇山人不可轻失也茶毕命奴子与钱羽愧之更着毁茶论与皇甫补阙善时鲍尚书防在越羽徃依焉冉送以序曰君子究孔释之名理穷歌诗之丽则逺墅孤岛通舟必行鱼梁钓矶随意而徃夫越地称山水之乡辕门当节钺之重鲍侯知子爱子者将解衣推食岂徒鱠镜水之鱼宿耶溪之月而已集并茶经今传\n张衆甫京口人隐居不务进取与皇甫御史曽友善精庐接近後各游四方曽寄张处士诗曰伏腊同鸡黍柴门闭雪天时宦亦有徴辟者守死善道卒不就衆甫诗婉媚绮错巧用文字工於兴喻文流中佳士也凡同在一时者有赵㣲明于逖蒋涣元季川俱山巅水涯苦学真士名同兰茝之芳志非银黄之慕吟咏性灵陶链衷素皆有佳篇不至湮落惜其行藏之大槩不见於记録故缺其考详焉〈按唐诗纪事蒋涣宰相智周之孙中进士第永大时为鸿胪卿日本使遗以金帛不纳唯取牋一杳以贻其副终吏部尚书元季川贞元大厯间诗人也原文不载似失考且蒋涣亦未可附隐逸也〉\n朱放字长通南阳人也〈按新唐书艺文志注放襄州人〉初居临汉水遭嵗歉南来卜隐剡溪镜湖间排青紫之念结庐云卧钓水樵山尝着白接离鹿裘笋履盘桓酒家时江浙名士如林风流儒雅俱从髙义如皇甫兄弟皎彻上人皆山人良友也大厯中嗣曹王臯镇江西辟为节度㕘谋有别同志诗曰潺湲寒溪上自此成离别回首望归人移舟逢暮雪频行识草树渐老伤年发唯有白云心为向东山月未几不乐鞅掌扁舟告还贞元二年诏举韬晦竒才特下聘礼拜左拾遗不就上表谢忘懐得失以此自终放工诗风度清越神情萧散非寻常之比集二巻今行於世\n卢仝范阳人初隐少室山号玉川子家甚贫惟图书堆积後卜居洛城破屋数间而已一奴长须不裹头一婢赤脚老无齿终日苦哦邻僧送米朝廷知其清介之节凡两备礼徴为谏议大夫不起时韩愈为河南令爱其操敬待之尝为恶少所恐诉于愈方为申理仝复虑盗憎主人愿罢之愈益服其度量元和间月蚀仝赋诗意讥切当时逆党愈极称工奄人稍恨之时王涯秉政胥怨于人及祸起仝偶与诸客㑹食涯书馆中因留宿吏卒掩捕仝曰我卢山人也於衆无怨何罪之有吏曰既云山人来宰相宅容非罪乎仓忙不能自理竟同甘露之祸仝老无发奄人于脑後加钉先是生子名添丁人以为䜟云仝性髙古介僻所见不凡近唐诗体无遗而仝之所作特异自成一家语尚竒谲读者难解识者易知後来仿效比拟遂为一格宗师有集一巻今传于世论曰古诗云枯鱼过河泣何时悔复及作书与鲂鱮相戒慎出入斯所以防前之覆辙也仝志懐霜雪操拟松筠深造括囊之髙夫何户庭之失噫一蹈非地旋踵逮殃玉石俱烂可不痛哉\n方干字雄飞桐庐人幼有清才散拙无营务大中中举进士不第隐居镜湖中湖北有茅斋湖西有松岛毎风清月明携穉子邻叟轻棹徃返甚惬素心所住水木幽閟一草一花俱能留客家贫蓄古琴行吟醉卧以自娱徐凝初有诗名一见干器之遂相师友因授格律干有赠凝诗云把得新诗草里论时谓反语为村里老疑干讥诮非也干貌陋兎缺性喜凌侮王大夫亷问浙东礼邀干至误三拜人号为方三拜王公嘉其操将荐于朝托吴融草表行有日王公以疾逝去事不果成干早嵗偕计徃来两京公卿好事者争延纳名竟不入手遂归无复荣辱之念浙中凡有园林名胜輙造主人留题几遍初李频学干为诗频及第诗僧清越贺云弟子已折桂先生犹灌园咸通末卒门人相与论德考行谥曰𤣥英先生乐安孙合等缀其遗诗三百七十余篇为十卷王赞论之曰镘肌涤骨氷莹霞绚嘉肴自将不吮余隽丽不葩芬苦不惧棘当其得志倐与神㑹词若未至意已独徃合亦论曰其秀也仙蘂于常花其鸣也灵鼍于衆响观其所述论不为过矣\n论曰古黔娄先生死曾参与门人来吊问曰先生终何以諡妻曰以康参曰先生存时食不充肤衣不盖形死则手足不敛傍无酒肉生不美死不荣何乐而諡为康哉妻曰昔先生国君用为相辞不受是有余贵也君馈粟三十锺辞不纳是有余富也先生甘天下之淡味安天下之卑位不戚戚于贫贱不遑遑于富贵求仁得仁求义得义諡之以康不亦宜乎方干韦布之士生称髙尚死諡𤣥英其梗槩大节庶几乎黔娄者耶\n陆龟䝉〈按新唐书龟䝉字鲁望〉幼而聪悟有髙致藏书万巻无声色之娱举进士不中从张抟游湖苏又至饶州三日无所诣刺史率官属就见龟䝉不乐拂衣去居松江甫里多所撰论性不喜与俗流交虽造门亦罕纳不乗马毎寒暑得中体无事时放扁舟挂篷席齎束书茶竈笔牀钓具鼓棹鸣榔太湖三万八千顷水天一色直入空明或徃来别浦所诣小不㑹意径徃不留自称江湖散人中和初遘疾卒吴融诔文曰霏漠漠淡涓涓春融冶秋鲜妍触即碎潭下月拭不灭玉上烟\n周朴字见素长乐人嵩山隐君也工为诗抒思尤艰毎有所得必极雕琢诗家称为月煆季链未及成篇已播人口取重当时如此贯休尤与徃还深为怜才而朴本无夺名竞利之心特以道尊德贵声价益超耳乾符中为巢贼所得以不屈竟及於祸逺近闻之莫不流涕林嵩得其诗百余篇为二卷僧栖浩序首今传於世唐求隐君也成都人值三灵改卜絶念鼎钟放旷疎逸出处悠然人多不识方外物表是所游心也酷耽吟调气韵清新每动竒趣工而不僻皆达者之词所行览不出二百里间无秋毫世俗之想\n论曰唐兴迨季叶治日少而乱日多虽草衣带索罕得安居当其时逺钓弋者多走山而逃海斯德而隐者矣自王君以下幽人间出皆逺腾长徃之士危行言逊重拨祸机糠核轩冕挂冠引退徃徃见之跃身炎冷之途标华黄绮之列虽或累聘丘园勉加冠佩适足以速深藏於薮泽耳然犹有不能逃白刄死非命焉夫蹟晦名彰风髙尘絶岂不以有翰墨之妙骚雅之美也哉文章为不朽之盛事也耻不为尧舜学者之所同志致君於三五懦夫尚知勇为今则舍声利而向山栖鹿冠乌几便於锦绣之服柴车草舍安於丹雘之厦藜羮不糁甘於五鼎之味素琴浊酒和於醇饴之奉樵青山渔白水足於佩金鱼而纡紫绶也时有不同也事有不侔也向子平曰吾故知富不如贫贵不如贱第未知死何如生此达人之言也易曰遯之时义大矣哉\n吴筠字贞节华隂人通经义美文辞举进士不中隐居南阳骑立山为道士天宝中𤣥宗遣使召至京师与语甚悦勅待诏翰林献𤣥纲三篇帝问道对曰深於道者惟老子五千言其余徒费纸札耳复问神仙冶链之术曰此野人之事积嵗月求之非人主所宜留意筠每陈説名教世务帝重之初筠爱㑹稽山水往来天台剡中与李白孔巢父相遇酬倡至是因荐於朝帝即遣使召之筠性髙鲠其待诏翰林时恃承恩顾髙力士素奉佛尝短筠於上前筠故多着赋文深诋释氏颇为通人所讥云後知天下将乱苦求还嵩山诏为立道观大歴间卒弟子諡为宗元先生善为诗有集十巻权德舆序之〈按本传未尝以筠为仙因总论与韩湘吕岩等并列故编次于此〉\n顾况字逋翁苏州人至德二年天子幸蜀江侍郎李希言下进士善为歌诗性诙谑不修检操工画山水初为韩晋江判官德宗时柳浑辅政荐为秘书郎况素善於李泌遂师事之得其服气之法能终日不食及泌相自谓当得达官久之迁着作郎及泌卒作海鸥咏嘲诮权贵大为所嫉被宪劾贬饶州司户作诗曰万里飞来为客鸟曽䝉丹凤借枝柯一朝凤去梧桐死满目鸱鸢奈尔何遂全家去隐茅山链金拜斗身轻如羽况暮年一子暴亡追悼哀切吟曰老人丧爱子日暮泣成血老人年七十不作多时别其年又生一子名非熊三嵗始言在㝠漠中闻父吟苦不忍乃来复生非熊後及第自长安归庆已不知况所在或云得长生诀仙去矣今有集二十巻传世皇甫湜为之序\n非熊姑苏人况之子也少俊悟一览辄能成诵工吟誉逺近性滑稽好辩颇杂笑言凌轹气熖子弟既犯衆怒挤排者纷然在举角艺三十年屈声被人耳㑹昌五年谏议大夫陈商放榜初上熟闻非熊诗价至是怪其不第勅有司进所试文章追榜放令及第刘得仁贺以诗曰愚为童稚时已解念君诗及得髙科早须逢圣主知授盱眙主簿不乐拜迎更厌鞭挞因弃官归隐王司马建送诗云江城柳色海门烟欲到茅山始下船知道君家当瀑布菖蒲潭在草堂前一时饯别俱吟僧名流不知所终或传住茅山十余年一旦遇异人相随入深谷不复出矣有诗一巻今行于世\n刘商〈按书録解题商字子夏唐诗纪事彭城人〉擢进士累官比部员外郎後出为汴州观察判官辞疾挂印归旧业商性好酒苦家贫常对花临月悠然独酌抗音长謡放适自遂赋诗曰春草秋风老此身一瓢长醉任家贫醒来还爱浮萍草漂寄官河不属人好神仙链金骨後隐义兴有集十巻传世\n韩湘字清夫愈之侄孙也长庆三年礼部侍郎王起下进士落魄不羁见趣髙逺尤耽苦吟公勉以经学曰湘所学公不知耶因赋诗以述志云青山云水窟此地是吾家後夜流琼液凌晨咀绦霞琴弹碧玉调炉炼白朱砂宝鼎存金虎元田养白鸦一瓢藏世界三尺斩妖邪解造逡巡酒能开顷刻花有人能学我同去㸔仙葩公笑曰子能夺造化乎湘曰此事甚易公为开樽湘聚土以盆覆之噀水良久开碧花三朶花片上有诗一聨云云横秦岭家何在雪拥蓝关马不前公甚怪异未喻其意曰他日騐之告去未几公以谏佛骨事谪潮州刺史一日途中见有人冒风雪从林间来视之乃湘也再拜马前曰公忆花上之句乎因询其地即蓝关嗟叹久之解鞍酒垆命酌足成诗曰一封朝奏九重天夕贬潮阳路八千本为圣朝除弊事岂期衰朽送残年云横秦岭家何在雪拥蓝关马不前知汝逺来应有意好收吾骨瘴江边又赠诗曰人才为世古来多如子雄文孰可过好待功名成就日却抽身去上烟萝湘笑而不答献诗别公曰举世都为名利醉惟吾来向道中醒他时定是飞昇去冲破秋空一㸃青遂别竟不知所终〈按湘本应附韩愈传以属方外故别编于此〉\n施肩吾字希圣睦州人元和十五年卢储榜进士登第後谢礼部陈侍郎云九重城里无亲识八百人中独姓施不待除授即东归张籍羣公吟饯人皆知有仙风道骨寜恋人间升斗耶而少存箕颍之情拍浮诗酒搴擥烟霞初读书五行俱下至是授真筌於仙长遂知逆顺颠倒之法与上中下精气神三田反覆之义以洪州西山十二真君羽化之地慕其真风髙蹈於此题诗曰重重道气结成神玉阙金堂逐日新若数西山得道者兼余即是十三人早尝赋闲居遣兴诗一百韵颇述初心大行於世着辨疑论一巻西山传道㑹真等记各一卷述气住则神住神住则形住为三住铭一巻及所为诗十巻自为之序今传\n陈陶字嵩伯鄱阳劔浦人尝举进士輙下为诗云中原不是无麟凤自是皇家结网疎颇负壮懐志逺心旷遂髙居不求进达恣游名山自称三教布衣大中中避乱入洪州西山学神仙咽气有得出入无间时严宇牧豫章慕其清操尝备斋供俯就山中挥麈谈终日欲试之遣小妓莲花徃待陶笑不答莲花赋诗求去曰莲花为号玉为腮珍重尚书送妾来处士不生巫峡梦虚劳云雨下阳台陶赋诗赠之云近来诗思清於水老去风情薄似云已向升天得门户锦衾深愧卓文君宇见诗益嘉贞节陶金骨己坚戒行通体夜必鹤氅焚香巨石上鸣金步虚礼星月少寐所止茅屋风雷汹汹不絶忽一日不见惟鼎竈杵臼依然开宝间有樵者入深谷犹见无恙後不知所终陶工赋诗无一㸃尘气於晚唐诸人中最得平淡要非时流所能企及者有文録十巻今传于世\n吕岩字洞賔京兆人礼部侍郎吕渭之孙也咸通初中第两调县令更值巢贼浩然发栖隐之志携家归终南自放迹江湖先是有锺离权字云房不知何代许人以丧乱避地太白间入紫阁石壁上得金诰玉籙深造希夷之㫖常髽髻衣槲叶隐见于世岩既笃志大道游览名山至太华遇云房知为异人拜以诗曰先生去後应须老乞与贫儒换骨丹云房许以法器因为着灵宝异法十二科悉究性命之㫖坐庐山中数十年金丹始就逢苦竹真人乃能驱役神鬼时移世换不复返也与陈图南音响相接或访其室中尝白襴角带卖墨於市得者皆成黄金徃徃遨逰洞庭潇湘湓浦间自称回道士时传已蝉蜕矣有术佩劔自笑曰吾仙人安用劔为所以断嗔爱烦恼耳常题寺壁曰三千里外无家客七百年前云水身後书云唐室进士今时神仙足蹑紫雾却归洞天又宿湖州沈东老家白酒满瓮恣意拍浮临去以石榴皮书壁间云西隣已富忧不足东老虽贫乐有余白酒酿来因好客黄金散尽为收书又尝负局奁於市为贾尚书淬古镜归忽不见留诗云袖里青蛇凌白日洞中仙果艳长春须知物外餐霞客不是尘中磨镜人又醉饮岳阳楼俯监洞庭时八月叶下水清君山如黛螺秋风浩荡遂按玉龙作一弄清音嘹亮金石可裂久之度古柳别去留诗云朝游南浦暮苍梧袖里青蛇胆气麤三入岳阳人不识朗吟飞过洞庭湖後徃来人间乗虚上下竟莫能测至今四百余年所在留题不可胜纪凡遇之者毎去後始觉悔无及矣盖其变化无穷吟咏不已此姑纪其大槩云\n陈抟字图南谯郡人少有才术经纶易象𤣥机尤所精究髙论骇俗少食寡思举进士不第时戈革满地遂隐居辟谷炼气撰指𤣥篇同道风偃僖宗召之封清虚处士居华山云台观每闭门独卧或兼旬不起周世宗召入禁中试之扃户月余始啓抟方熟寐齁䶎觉即辞去赋诗云十年踪迹走红尘囘首青山入梦频紫陌纵荣争及睡朱门虽贵不如贫愁闻劔㦸扶危主闷听笙歌聒醉人携取旧书归旧隐野花啼鸟一般春还山後因乗驴游华隂市见邮传甚急问知宋祖登基抟抵掌长笑曰天下自此定矣太宗徴赴戴华阳巾草屦垂縧与万乗分庭抗礼赐号希夷先生时居云台四十年仅及百嵗帝赠诗云曽向前朝出白云後来消息杳无闻如今已肯随徴召总把三峯乞与君真宗复召不起为谢表畧曰明时闲客唐室书生尧道昌而优容许由汉世盛而善从商皓况性同猿鹤心若土灰败荷制服脱箨裁冠体有青毛足无草屦苟临轩陛贻笑圣朝数行丹诏徒教彩凤衔来一片野心已被白云留住咏嘲风月之清笑傲烟霞之表遂性所乐何得何言後凿石室於莲华峯一旦坐其中羽化而去有诗集今传如洛阳潘阆逍遥河南种放明逸钱塘林逋君复钜鹿魏野仲先青州李之才挺之天水穆修伯长皆从学先生一流髙士俱有诗名大节详见宋史云\n论曰晋嵇康论神仙非积学所能致斯言信哉原其本自天灵有异凡品仙风道骨迥凌云表厯观传记所载雾隐乎岩巅霞寓于尘外崆峒羡门以下清流相望由来尚矣虽解化一事似或𤣥㣲正非假房中黄白之小端从而服食颐养能尽其道者也不损上药愈益下田熊经鸟伸纳新吐故无七情以夺魂魄无百虑以煎肺肝庶几指识𤣥户引身长年然後一跃顿乔松之逸驭也今夫指青山首驾卧白云振衣纷长徃于斯世遗髙风於无穷及见其人吾亦愿从之游耳韩湘控鹤於前吕岩骖鸾於後凡其题咏篇什铿锵振作皆天成云汉不假安排自非咀嚼氷玉呼吸烟霏孰能至此寜好事者为之多见其不知量也吴筠张志和施肩吾刘商陈陶顾况等髙躅可数皆颉颃於元化中者欤\n灵一〈按唐诗纪事灵一大厯贞元间僧也〉童子出家缾鉢外无所有天性超颖追踪谢客隐居麻源第三谷中结茅读书後白业精进居若耶溪云门寺从学者四方而至矣\n皎然字清昼吴兴人俗姓谢宋灵运之十世孙也初入道肄业杼山与灵彻陆羽同居妙喜寺羽於寺傍创亭以癸丑嵗癸卯朔癸亥日落成湖州刺史顔真卿名以三癸皎然赋诗时称三絶真卿尝於郡斋集文士撰韵海镜源与其论着由是声价籍甚贞元中集贤御书院取髙僧集得上人文十巻藏之刺史于頔为之序李端在匡岳依止称门生一时名公俱相友善题云清昼上人是也时韦应物以古淡矫俗公尝拟其格得数解为贽韦心疑之明日又録旧制以见始被领畧曰人各有长盖自天分子而为我失故步矣但以所诣自名可也公心服之徃时住西林寺定余多暇因撰序作诗体式兼评古今人诗为昼公诗式五巻及撰诗评三巻皆议论精当取舍从公整顿狂澜出色骚雅公性放逸不缚於常律初房太尉琯早嵗隐终南峻壁之下徃徃闻湫中龙吟声清而静涤人雅想时有僧潜戛三金以写之惟铜酷似房公他日至山寺闻林岭间有声因命僧出其器叹曰此真龙吟也大厯间有秦僧传至桐江皎然戛铜椀效之以警深寂缁人有献讥者公曰此达僧之事可以嬉禅尔曹胡凝滞於物而以琐行自拘耶时人髙之公外学超然兴㑹闲适居第一流不疑也\n无可髙僧也〈按书録解题无可贾岛弟〉工五言诗律调谨严属兴清越比物以意谓之象外句如曰听雨寒更尽开门落叶深〈按此传有阙文〉\n清塞字南卿居庐岳为浮屠客南徐亦久後来少室终南间俗姓周名贺工为近体诗格调清雅与贾岛无可齐名宝厯中姚合守钱塘因携书投刺以丐品第合延待甚异见其哭僧诗云冻须亡夜剃遗偈病中书大爱之因加以冠巾使复姓字时夏腊已髙荣望落落竟徃依名山诸尊宿而终诗一巻今传〈按周贺一传本不应列诗僧中今按本文清塞云云其体例与他僧不殊故编于此〉\n虚中袁州人少脱俗从佛而读书不辍工吟咏居玉笥山二十寒暑後来游潇湘与齐已尚顔栖蟾为诗友住湘西栗城寺司空图悬车告老却扫闭门天下懐仰虚中欲造见论交未果因归华山寄以诗曰门径放莎埀徃来投刺稀有时开御札特地挂朝衣岳信僧传去天香鹤带归他时周召化无复更衰㣲图得诗大喜言懐云十年华岳山前住只得虚中一首诗其见重如此贯休〈按唐诗纪事姓姜氏字徳隐婺州兰溪人〉风骚之外精於笔札成中令问其笔法休曰此事须登坛而授安可草草而言成衔之递放黔中以病鹤诗见意曰见説气清邪不入不知尔病自何来初昭宗以武肃王钱璆平董昌功拜镇东军节度使自称吴越王僧贯休时居灵隐徃投诗贺中聨云满堂花醉三千客一劒霜寒十四州武肃大喜然僭侈之心始张遣人谕令改为四十州乃可相见休性躁急答曰州亦难添诗亦难改余孤云野鹤何天不可飞即日褁衣鉢拂袖而去\n论曰贯休天赋敏速之才笔吐猛鋭之意昔谓龙象蹴踏非驴所堪果僧中之一豪也\n齐己长沙人〈按唐诗纪事齐己俗姓胡名得生〉早失怙恃七嵗颖悟为大沩山寺司牧徃徃抒思取竹枝画牛背为小诗耆宿异之遂共推挽入戒风度日改声价益隆过豫章时陈陶近巳仙去已留题有云夜过修竹寺醉打老僧门至宜春投诗郑都官云自封修药院别下着僧床谷曰善则善矣一字未安经数日来曰别埽如何谷嘉赏结为诗友\n薛涛字洪度成都乐妓也性辨慧娴翰墨居浣花里种菖蒲满门傍即东北走长安道也徃来车马留连元和中元㣲之使蜀宻意求访府公严司空知之遣涛徃侍㣲之登翰林以诗寄之曰锦江滑腻峨嵋秀幻出文君与薛涛言语巧偷鹦鹉舌文章分得凤凰毛纷纷词客皆停笔个个公侯欲梦刀别後相思隔烟水菖蒲花发五云髙及武元衡入相奏授校书郎蜀人呼妓为校书自涛始也後胡曽赠诗曰万里桥边女校书枇杷花下闭门居扫眉才子知多少管领春风总不如涛工为小诗惜成都牋幅大遂皆制狭之人以为便名曰薛涛牋且机警敏㨗座间谈笑风生髙骈镇蜀门日命之佐酒行一字叶音令且得形象曰口似没梁斗答曰川似三条椽公曰奈一条曲何曰相公为西川节度尚用一破斗况穷酒佐杂一曲椽何足怪哉其敏捷类此特多座客赏叹其所作诗稍窥良匠词意不苟情尽笔墨翰苑崇髙辄能攀附殊不意裙裾之中出此异物岂得以匪人而弃其学哉太和中卒有锦江集五巻今传中多名公赠答云\n李季兰名冶以字行峡中人女道士也美姿容神情萧散专心翰墨善弹琴尤工格律当时才子颇夸纎丽殊少荒艳之态始年六嵗时作蔷薇诗云经时不架却心绪乱纵横其父见曰此女聪黠非常恐为失行妇人後以交游文士㣲泄风声皆出乎轻薄之口夫士有百行女唯四德季兰则不然形气既雄诗意亦荡自鲍昭以下罕有其伦时徃来剡中与山人陆羽上人皎然意甚相得皎然尝有诗云天女来相试将花欲染衣禅心竟不起还捧旧花归其谑浪至此又尝㑹诸贤於乌程开元寺知河间刘长卿有隂重之疾诮曰山气日夕佳刘应声曰衆鸟欣有托举坐大笑论者两美之天宝间𤣥宗闻其诗才诏赴阙留宫中月余优赐甚厚遣归故山评者谓上比班姬则不足下比韩英则有余亦一俊姬也有集今传于世\n鱼𤣥机长安人女道士也性聪慧好读书及笄为李亿补阙侍宠夫人妬不能容亿遣𨽻咸宜观披戴有怨李诗云易求无价宝难得有心郎与李郢端公同巷居止接近诗筒徃返尝登崇真观南楼观新进士题名榜赋诗曰云峯满目放春晴厯厯银鈎指下生自恨罗衣掩诗句举头空羡榜中名观其志意激切使为一男子必有用之才作者颇赏怜之\n论曰诗云关雎乐得淑女以配君子忧在进贤不淫其色哀窈窕思贤才而无伤善之心焉故古诗之道各存六义然终归于正不离乎雅是以古昔贤妇人散情文墨班班简牍未易槩而论之後来班姬伤秋扇以暂恩谢娥咏絮云而同素大家七诫执者修省蔡琰胡笳闻而心折率以明白之操徽美之诚欲见於悠逺寓文以宣情含亳而见志使人击节沾洒弹指追念良有谓焉噫笔墨固非女子之事亦在用之如何耳苟天有可逃礼不必备则词为自献之具诗有妬情之作衣服酒食无闲静之容铅华膏泽多鲜饰之态故不相宜矣是播恶於衆何关雎之义哉厯观唐以雅道奬士类而闺合英秀亦能熏染锦心绣口蕙情兰性是可尚矣中间如李季兰鱼𤣥机皆跃出方外修清净之教陶写幽懐留连光景逍遥闲暇之功无非云水之念与名儒比隆珠徃琼复然浮艳委托之心终不能尽白璧㣲瑕惟在此耳薛涛流落歌舞以灵慧获名当时此亦难矣三者既不可畧他如刘媛刘云鲍君徽崔仲容道士元淳薛媪崔公达张窈窕程长文梁琼亷氏姚月华裴羽仙刘瑶常浩葛鵶儿崔莺莺谭意哥户部侍郎吉中孚妻张夫人鲍参军妻文姬杜羔妻赵氏张建封妾盻盻南楚材妻薛媛等皆雅擅华藻才色双美者也或望幸离宫伤宠後掖或从军万里断絶音耗或祗役连年迢遥风水或为荡子妻或为商人妇花雨春夜月露秋天𤣥鸟将谢宾鸿来届捣锦石之流黄织回文於缃绮魂梦飞逺闗山到难当此时也濡毫命素写怨书懐一语一聨俱堪堕泪至若间以丰丽杂以纎穠导淫奔之约叙久旷之情不假緑琴但飞红纸中间不能免焉尺有短而寸有长故未欲椎埋之云尔\n杂传记中多録鬼神灵怪之词哀调深情不异畴昔然影响所托理亦荒唐故不能一一尽之〈按本文所云则原书于鬼神灵怪之词当亦畧为采录今俱佚矣此条当是其总论结语以"}]};